/* Tạo tự động bởi tools/build-vocab.js từ sheet "SAT Vocab-old" – đừng sửa tay */
Vocab.addDeck({"id":"old1","sets":[{"n":"Buổi 1","c":[{"t":"abstruse","p":"adj","d":"khó hiểu/trừu tượng","e":"The professor's lecture on quantum mechanics was so abstruse that many students left feeling confused.","ev":"Bài giảng của giáo sư về cơ học lượng tử quá trừu tượng đến nỗi nhiều sinh viên ra về với cảm giác bối rối.","k":"abstruse"},{"t":"apt","p":"adjective","d":"thích hợp","e":"She has an apt ability to solve complex problems quickly and efficiently.","ev":"Cô ấy có khả năng nhạy bén trong việc giải quyết các vấn đề phức tạp một cách nhanh chóng và hiệu quả.","k":"apt"},{"t":"cajole","p":"verb","d":"dỗ dành, nịnh hót","e":"He tried to cajole his friend into going to the party by promising a free dinner.","ev":"Anh ấy đã cố gắng nịnh nọt bạn mình đi dự tiệc bằng cách hứa sẽ đãi bữa tối miễn phí.","k":"cajole"},{"t":"compendious","p":"adjective","d":"tóm tắt, ngắn gọn","e":"The book provides a compendious overview of modern philosophy in just a few chapters.","ev":"Cuốn sách cung cấp cái nhìn tổng quát ngắn gọn về triết học hiện đại chỉ trong vài chương.","k":"compendious"},{"t":"concur","p":"verb","d":"đồng ý","e":"The committee members concurred that the project should be postponed until further funding is secured.","ev":"Các thành viên trong ủy ban đồng ý rằng dự án nên được hoãn lại cho đến khi có thêm kinh phí.","k":"concur"},{"t":"delineate","p":"verb","d":"miêu tả, giải thích, phân định","e":"The report delineates the key differences between the two proposed plans.","ev":"Báo cáo đã phác thảo rõ ràng những khác biệt chính giữa hai kế hoạch đề xuất.","k":"delineate"},{"t":"digress(ion)","p":"verb/noun","d":"lạc đề","e":"During the presentation, she took a brief digression to share a personal story.","ev":"Trong buổi thuyết trình, cô ấy đã tạm thời lạc đề để chia sẻ một câu chuyện cá nhân.","k":"digress(ion)"},{"t":"elucidate","p":"verb","d":"Làm rõ","e":"The teacher used diagrams to elucidate the complex topic for her students.","ev":"Giáo viên đã sử dụng sơ đồ để làm rõ chủ đề phức tạp cho học sinh của mình.","k":"elucidate"},{"t":"embroil(ed)","p":"verb","d":"kéo vào, làm rối rắm","e":"The company became embroiled in a legal dispute over its new product line.","ev":"Công ty đã bị cuốn vào một tranh chấp pháp lý liên quan đến dòng sản phẩm mới.","k":"embroil(ed)"},{"t":"empiric(al)","p":"adjective","d":"Dựa trên kinh nghiệm","e":"The research is based on empirical evidence gathered from experiments.","ev":"Nghiên cứu này dựa trên bằng chứng thực nghiệm thu thập từ các cuộc thí nghiệm.","k":"empiric(al)"},{"t":"enumerate","p":"verb","d":"Liệt kê","e":"The speaker began to enumerate the reasons for the project's success.","ev":"Người nói đã bắt đầu liệt kê những lý do cho sự thành công của dự án.","k":"enumerate"},{"t":"epitome, epitomize","p":"noun, verb","d":"Ví dụ điển hình, tóm tắt","e":"She is the epitome of grace and elegance, and her performance perfectly epitomized the theme of the ballet.","ev":"Cô ấy là hình mẫu của sự duyên dáng và thanh lịch, và màn trình diễn của cô hoàn toàn tiêu biểu cho chủ đề của buổi ballet.","k":"epitome, epitomize"},{"t":"equivocal","p":"adjective","d":"Mơ hồ","e":"His equivocal response left everyone unsure about his true intentions.","ev":"Phản ứng không rõ ràng của anh ấy khiến mọi người không chắc chắn về ý định thực sự của anh.","k":"equivocal"},{"t":"exemplar","p":"noun","d":"Mẫu mực","e":"She serves as an exemplar of hard work and dedication for her colleagues.","ev":"Cô ấy là hình mẫu của sự chăm chỉ và cống hiến cho đồng nghiệp của mình.","k":"exemplar"},{"t":"exhort","p":"verb","d":"Khuyến khích, hối thúc","e":"The coach exhorted his team to give their best effort in the final game.","ev":"Huấn luyện viên đã khuyến khích đội bóng của mình nỗ lực hết sức trong trận đấu cuối cùng.","k":"exhort"},{"t":"expedient","p":"adjective/noun","d":"Thuận lợi, thiết thực","e":"It was expedient for the manager to make a quick decision to avoid further delays.","ev":"Việc đưa ra quyết định nhanh chóng là điều cần thiết cho người quản lý để tránh trì hoãn thêm.","k":"expedient"},{"t":"fathom (verb)","p":"verb","d":"Hiểu, thấu hiểu","e":"It’s hard to fathom the depth of the ocean from the shore.","ev":"Thật khó để hiểu được độ sâu của đại dương từ bờ biển.","k":"fathom (verb)"},{"t":"flagrant","p":"adjective","d":"Rõ ràng, nghiêm trọng","e":"The athlete's flagrant violation of the rules led to his disqualification.","ev":"Việc vi phạm rõ ràng của vận động viên đã dẫn đến việc anh bị loại.","k":"flagrant"},{"t":"florid(ity)","p":"adjective/noun","d":"Hào nhoáng, rực rỡ","e":"The author's floridity in writing can make even simple ideas seem extravagant.","ev":"Sự hoa mỹ trong cách viết của tác giả có thể khiến ngay cả những ý tưởng đơn giản cũng trở nên cầu kỳ.","k":"florid(ity)"},{"t":"incongruity, \nincongruous","p":"noun/adjective","d":"Sự không phù hợp, không tương","e":"The incongruity of wearing a winter coat in summer made everyone laugh.","ev":"Sự không phù hợp của việc mặc áo khoác mùa đông vào mùa hè khiến mọi người buồn cười.","k":"incongruity, incongruous"}]},{"n":"Buổi 2","c":[{"t":"ineffable","p":"adjective","d":"Không thể diễn tả bằng lời","e":"The beauty of the sunset was ineffable; no words could capture its essence.","ev":"Vẻ đẹp của hoàng hôn thật không thể diễn tả; không có từ nào có thể diễn tả được bản chất của nó.","k":"ineffable"},{"t":"innuendo","p":"noun","d":"Lời bóng gió","e":"His remarks were filled with innuendo, suggesting more than he actually said.","ev":"Những nhận xét của anh ấy đầy bóng gió, ám chỉ nhiều hơn những gì anh thực sự nói.","k":"innuendo"},{"t":"laconic","p":"adjective","d":"Ngắn gọn","e":"The speaker was laconic, delivering his message in just a few words.","ev":"Người phát biểu rất ngắn gọn, truyền đạt thông điệp của mình chỉ trong vài từ.","k":"laconic"},{"t":"lucid","p":"adjective","d":"Rõ ràng","e":"Her explanation was so lucid that everyone understood the complex concept immediately.","ev":"Giải thích của cô ấy rõ ràng đến nỗi mọi người ngay lập tức hiểu được khái niệm phức tạp.","k":"lucid"},{"t":"nebulous","p":"adjective","d":"Mơ hồ","e":"The directions were nebulous, making it hard to find the location.","ev":"Các chỉ dẫn rất mơ hồ, khiến việc tìm kiếm địa điểm trở nên khó khăn.","k":"nebulous"},{"t":"nuance","p":"noun","d":"Sắc thái","e":"The nuances of her expression revealed her true feelings about the situation.","ev":"Những sắc thái trong biểu cảm của cô ấy tiết lộ cảm xúc thật sự của cô về tình huống.","k":"nuance"},{"t":"paradigm","p":"noun","d":"Mẫu hình","e":"The new paradigm in technology is changing how we communicate.","ev":"Mô hình mới trong công nghệ đang thay đổi cách chúng ta giao tiếp.","k":"paradigm"},{"t":"prattle","p":"verb/noun","d":"Nói nhảm","e":"They engaged in prattle, discussing trivial matters instead of the main topic.","ev":"Họ đã nói nhảm, bàn về những vấn đề tầm thường thay vì chủ đề chính.","k":"prattle"},{"t":"pronouncement","p":"noun","d":"Lời tuyên bố","e":"The pronouncement from the committee shocked everyone in attendance.","ev":"Tuyên bố từ ủy ban khiến mọi người có mặt đều sốc.","k":"pronouncement"},{"t":"proponent","p":"noun","d":"Người ủng hộ","e":"She is a strong proponent of environmental protection and sustainability.","ev":"Cô ấy là một người ủng hộ mạnh mẽ cho việc bảo vệ môi trường và sự bền vững.","k":"proponent"},{"t":"prosaic","p":"adjective","d":"Tầm thường, không thú vị","e":"His writing was often criticized as prosaic and lacking imagination.","ev":"Văn phong của anh ấy thường bị chỉ trích là tầm thường và thiếu sự sáng tạo.","k":"prosaic"},{"t":"rebuttal","p":"noun","d":"Phản bác","e":"The lawyer's rebuttal effectively countered the accusations made against her client.","ev":"Sự phản biện của luật sư đã bác bỏ hiệu quả những cáo buộc chống lại thân chủ của cô.","k":"rebuttal"},{"t":"recant","p":"verb","d":"Rút lại","e":"After much consideration, he decided to recant his earlier statement.","ev":"Sau nhiều cân nhắc, anh đã quyết định thu hồi tuyên bố trước đó của mình.","k":"recant"},{"t":"repudiate","p":"verb","d":"Từ chối","e":"The politician chose to repudiate the rumors about his involvement in the scandal.","ev":"Chính trị gia đã chọn bác bỏ những tin đồn về sự tham gia của mình vào vụ bê bối.","k":"repudiate"},{"t":"rescind","p":"verb","d":"Hủy bỏ","e":"The organization decided to rescind the policy due to public outcry.","ev":"Tổ chức đã quyết định hủy bỏ chính sách do phản đối từ công chúng.","k":"rescind"},{"t":"rhetoric(al), \nrhetorician","p":"noun/adjective","d":"Nghệ thuật hùng biện, nhà hùng","e":"His rhetorical skills captivated the audience during the debate.","ev":"Kỹ năng hùng biện của anh ấy đã thu hút sự chú ý của khán giả trong cuộc tranh luận.","k":"rhetoric(al), rhetorician"},{"t":"scrutinize, scrutiny","p":"verb/noun","d":"Xem xét kỹ lưỡng, sự xem","e":"She needed to scrutinize the document for any errors before submission.","ev":"Cô ấy cần xem xét kỹ lưỡng tài liệu để tìm bất kỳ lỗi nào trước khi nộp.","k":"scrutinize, scrutiny"},{"t":"simile","p":"noun","d":"So sánh","e":"The author used a simile to illustrate the character’s feelings, comparing her sadness to a rainstorm.","ev":"Tác giả đã sử dụng phép so sánh để minh họa cảm xúc của nhân vật, so sánh nỗi buồn của cô với cơn bão mưa.","k":"simile"},{"t":"tangential","p":"adjective","d":"Không liên quan trực tiếp","e":"His comments were tangential to the main discussion and did not add much value.","ev":"Những nhận xét của anh ấy không liên quan đến cuộc thảo luận chính và không mang lại giá trị gì nhiều.","k":"tangential"},{"t":"treatise","p":"noun","d":"Luận án","e":"The treatise on philosophy provided a deep analysis of existential questions.","ev":"Luận văn về triết học đã cung cấp một phân tích sâu sắc về các câu hỏi tồn tại.","k":"treatise"}]},{"n":"Buổi 3","c":[{"t":"verbose","p":"adjective","d":"Dài dòng","e":"His verbose speech included unnecessary details that bored the audience.","ev":"Bài phát biểu dài dòng của anh ấy bao gồm những chi tiết không cần thiết khiến khán giả chán nản.","k":"verbose"},{"t":"aura","p":"noun","d":"Hào quang","e":"She had an aura of confidence that drew people to her.","ev":"Cô ấy có một hào quang tự tin thu hút mọi người đến với mình.","k":"aura"},{"t":"bombastic","p":"adjective","d":"Hào nhoáng, phô trương","e":"The politician's bombastic rhetoric failed to convince the voters.","ev":"Lời hùng biện phô trương của chính trị gia đã không thuyết phục được cử tri.","k":"bombastic"},{"t":"buoyant","p":"adjective","d":"Tươi vui, nổi bật","e":"Despite the challenges, she remained buoyant and optimistic about the future.","ev":"Mặc dù gặp nhiều khó khăn, cô vẫn giữ tinh thần phấn chấn và lạc quan về tương lai.","k":"buoyant"},{"t":"callous","p":"adjective","d":"Vô cảm","e":"His callous remarks about the tragedy upset many people.","ev":"Những nhận xét lạnh lùng của anh về thảm kịch đã khiến nhiều người khó chịu.","k":"callous"},{"t":"cantankerous(ness)","p":"adjective/noun","d":"Cáu kỉnh, tính cáu kỉnh","e":"The cantankerous old man often argued with his neighbors over trivial matters.","ev":"Người đàn ông khó tính thường cãi nhau với hàng xóm về những vấn đề tầm thường.","k":"cantankerous(ness)"},{"t":"capricious","p":"adjective","d":"Thay đổi thất thường","e":"Her capricious nature made it difficult to predict her reactions.","ev":"Tính cách thất thường của cô khiến việc dự đoán phản ứng của cô trở nên khó khăn.","k":"capricious"},{"t":"caustic","p":"adjective","d":"Châm biếm, mỉa mai","e":"His caustic comments hurt many feelings and created tension in the room.","ev":"Những nhận xét châm biếm của anh đã làm tổn thương nhiều cảm xúc và tạo ra căng thẳng trong phòng.","k":"caustic"},{"t":"convivial","p":"adjective","d":"Thân thiện, vui vẻ","e":"The party was a convivial gathering filled with laughter and good food.","ev":"Bữa tiệc là một buổi tụ tập vui vẻ đầy tiếng cười và món ăn ngon.","k":"convivial"},{"t":"demonstrative","p":"adjective","d":"Cởi mở, thể hiện cảm xúc","e":"He was demonstrative in his affection, often hugging and kissing his friends.","ev":"Anh ấy thể hiện tình cảm một cách rõ ràng, thường ôm và hôn bạn bè.","k":"demonstrative"},{"t":"despondent","p":"adjective","d":"Chán nản","e":"After losing his job, he felt despondent and lost.","ev":"Sau khi mất việc, anh cảm thấy tuyệt vọng và lạc lõng.","k":"despondent"},{"t":"diffident, diffidence","p":"adjective/noun","d":"Thiếu tự tin, sự thiếu tự","e":"Her diffident manner made her hesitant to speak up in meetings.","ev":"Cách cư xử nhút nhát của cô khiến cô do dự khi phát biểu trong các cuộc họp.","k":"diffident, diffidence"},{"t":"discomfited","p":"adjective","d":"Bối rối","e":"She felt discomfited by the unexpected question during the interview.","ev":"Cô cảm thấy khó chịu trước câu hỏi bất ngờ trong buổi phỏng vấn.","k":"discomfited"},{"t":"disillusionment","p":"noun","d":"Sự thất vọng","e":"The disillusionment with the political system led many to lose faith in democracy.","ev":"Sự thất vọng với hệ thống chính trị đã khiến nhiều người mất niềm tin vào nền dân chủ.","k":"disillusionment"},{"t":"dispassionate","p":"adjective","d":"Vô cảm, không bị cảm xúc chi","e":"He approached the situation with a dispassionate view, analyzing the facts without emotion.","ev":"Anh tiếp cận tình huống với cái nhìn lạnh lùng, phân tích các sự kiện mà không có cảm xúc.","k":"dispassionate"},{"t":"elated, elation","p":"adjective/noun","d":"Hân hoan, sự hân hoan","e":"She felt elated after receiving the good news about her promotion.","ev":"Cô cảm thấy hạnh phúc sau khi nhận được tin tốt về việc thăng chức.","k":"elated, elation"},{"t":"evoke","p":"verb","d":"Gợi lên","e":"The song evoked memories of her childhood and made her nostalgic.","ev":"Bài hát gợi lại những kỷ niệm về thời thơ ấu của cô và khiến cô cảm thấy hoài niệm.","k":"evoke"},{"t":"felicitous","p":"adjective","d":"Thích hợp, hạnh phúc","e":"His felicitous remarks lightened the mood during the serious discussion.","ev":"Những nhận xét phù hợp của anh đã làm nhẹ bầu không khí trong cuộc thảo luận nghiêm túc.","k":"felicitous"},{"t":"forlorn","p":"adjective","d":"Cô đơn, bị bỏ rơi","e":"She sat forlorn on the bench, waiting for someone who never arrived.","ev":"Cô ngồi đơn độc trên ghế, chờ đợi một người không bao giờ đến.","k":"forlorn"},{"t":"fortitude","p":"noun","d":"Sự dũng cảm","e":"He showed great fortitude in facing the challenges of his illness.","ev":"Anh đã thể hiện được sự dũng cảm trong việc đối mặt với những thử thách của bệnh tật.","k":"fortitude"}]},{"n":"Buổi 4","c":[{"t":"furor","p":"noun","d":"Sự phẫn nộ, cơn cuồng nộ","e":"The furor over the new policy caused widespread protests across the city.","ev":"Cuộc phẫn nộ về chính sách mới đã gây ra các cuộc biểu tình lan rộng khắp thành phố.","k":"furor"},{"t":"histrionic","p":"adjective","d":"Kịch tính, thái quá","e":"His histrionic behavior during the meeting drew eye rolls from his colleagues.","ev":"Cách cư xử kịch tính của anh ấy trong cuộc họp đã khiến đồng nghiệp phải lắc đầu.","k":"histrionic"},{"t":"idyllic","p":"adjective","d":"Thơ mộng","e":"They spent their vacation in an idyllic village surrounded by mountains and rivers.","ev":"Họ đã dành kỳ nghỉ của mình ở một ngôi làng idylic được bao quanh bởi núi và sông.","k":"idyllic"},{"t":"impetuous","p":"adjective","d":"Hấp tấp","e":"Her impetuous decision to quit her job surprised everyone.","ev":"Quyết định bốc đồng của cô để bỏ việc đã khiến mọi người ngạc nhiên.","k":"impetuous"},{"t":"irate","p":"adjective","d":"Giận dữ","e":"He became irate when he found out his car had been towed.","ev":"Anh trở nên tức giận khi phát hiện ra xe của mình đã bị kéo đi.","k":"irate"},{"t":"jaded","p":"adjective","d":"Mệt mỏi, chán ngấy","e":"After years in the industry, she felt jaded and disillusioned.","ev":"Sau nhiều năm trong ngành, cô cảm thấy mệt mỏi và thất vọng.","k":"jaded"},{"t":"jocular","p":"adjective","d":"Hài hước","e":"His jocular personality made him the life of the party.","ev":"Tính cách vui vẻ của anh đã khiến anh trở thành tâm điểm của bữa tiệc.","k":"jocular"},{"t":"jovial","p":"adjective","d":"Vui vẻ, thân thiện","e":"The jovial atmosphere at the family gathering made everyone feel welcome.","ev":"Bầu không khí vui vẻ trong buổi họp mặt gia đình khiến mọi người cảm thấy được chào đón.","k":"jovial"},{"t":"maudlin","p":"adjective","d":"Đẫm nước mắt, sướt mướt","e":"She became maudlin after a few drinks, reminiscing about her high school days.","ev":"Cô trở nên sướt mướt sau vài ly, nhớ lại những ngày ở trường trung học.","k":"maudlin"},{"t":"melancholy","p":"adjective/noun","d":"Buồn bã","e":"A sense of melancholy hung over the town after the festival ended.","ev":"Một cảm giác u buồn bao trùm thị trấn sau khi lễ hội kết thúc.","k":"melancholy"},{"t":"mercurial","p":"adjective","d":"Thay đổi nhanh chóng","e":"His mercurial temperament made it hard for people to know how he would react.","ev":"Tính cách thất thường của anh khiến mọi người khó đoán được anh sẽ phản ứng như thế nào.","k":"mercurial"},{"t":"morose","p":"adjective","d":"U sầu","e":"He had a morose expression after receiving the bad news.","ev":"Anh có vẻ ủ rũ sau khi nhận được tin xấu.","k":"morose"},{"t":"peevish","p":"adjective","d":"Cáu kỉnh","e":"She was peevish and irritable after missing her morning coffee.","ev":"Cô trở nên cáu kỉnh và khó chịu sau khi bỏ lỡ ly cà phê buổi sáng.","k":"peevish"},{"t":"penchant","p":"noun","d":"Sự ưa thích","e":"He had a penchant for collecting rare coins from around the world.","ev":"Anh có sở thích sưu tầm những đồng tiền hiếm từ khắp nơi trên thế giới.","k":"penchant"},{"t":"perfunctory","p":"adjective","d":"Hời hợt","e":"His perfunctory response to the question showed his lack of interest.","ev":"Phản ứng hời hợt của anh đối với câu hỏi cho thấy sự thiếu quan tâm của anh.","k":"perfunctory"},{"t":"petulant","p":"adjective","d":"Nóng nảy","e":"The petulant child threw a tantrum when he didn’t get his way.","ev":"Đứa trẻ cáu kỉnh đã ăn vạ khi không được như ý muốn.","k":"petulant"},{"t":"profound, \nprofundity","p":"adjective/noun","d":"Sâu sắc, sự sâu sắc","e":"Her profound insights into human nature were well-received by the audience.","ev":"Những hiểu biết sâu sắc của cô về bản chất con người đã được khán giả đón nhận nồng nhiệt.","k":"profound, profundity"},{"t":"propensity","p":"noun","d":"Xu hướng","e":"He has a propensity for taking risks that often leads to unexpected outcomes.","ev":"Anh có xu hướng mạo hiểm, điều này thường dẫn đến những kết quả bất ngờ.","k":"propensity"},{"t":"repugnant","p":"adjective","d":"Đáng ghê tởm","e":"The repugnant behavior of the character in the film made it hard to watch.","ev":"Hành vi ghê tởm của nhân vật trong bộ phim khiến việc xem trở nên khó khăn.","k":"repugnant"},{"t":"reticent, reticence","p":"adjective/noun","d":"Ít nói, sự ít nói","e":"She was reticent about her personal life, preferring to keep her thoughts private.","ev":"Cô ấy rất kín đáo về cuộc sống cá nhân, thích giữ suy nghĩ của mình trong im lặng.","k":"reticent, reticence"}]},{"n":"Buổi 5","c":[{"t":"sanguine","p":"adjective","d":"Lạc quan","e":"Despite the challenges ahead, she remained sanguine about the future.","ev":"Dù đối mặt với những thử thách phía trước, cô vẫn lạc quan về tương lai.","k":"sanguine"},{"t":"solace","p":"noun/verb","d":"Sự an ủi","e":"He found solace in music during difficult times.","ev":"Anh tìm thấy sự an ủi trong âm nhạc trong những lúc khó khăn.","k":"solace"},{"t":"somber","p":"adjective","d":"U ám","e":"The somber mood at the funeral reflected the loss felt by everyone.","ev":"Bầu không khí u ám tại tang lễ phản ánh nỗi mất mát mà mọi người đều cảm thấy.","k":"somber"},{"t":"temperamental","p":"adjective","d":"Dễ thay đổi tâm trạng","e":"His temperamental nature made it hard for his friends to predict his reactions.","ev":"Tính khí thất thường của anh khiến bạn bè khó đoán được phản ứng của anh.","k":"temperamental"},{"t":"trepidation","p":"noun","d":"Sự lo lắng","e":"She felt a sense of trepidation before her big presentation.","ev":"Cô cảm thấy lo lắng trước bài thuyết trình lớn của mình.","k":"trepidation"},{"t":"truculent, \ntruculence","p":"adjective/noun","d":"Hiếu chiến, sự hiếu chiến","e":"The truculent attitude of the player led to several penalties during the game.","ev":"Thái độ hung hãn của cầu thủ đã dẫn đến nhiều hình phạt trong trận đấu.","k":"truculent, truculence"},{"t":"vicarious","p":"adjective","d":"Thay thế","e":"His vicarious experiences through books allowed him to explore the world without leaving home.","ev":"Những trải nghiệm gián tiếp của anh qua sách cho phép anh khám phá thế giới mà không cần rời khỏi nhà.","k":"vicarious"},{"t":"wrath","p":"noun","d":"Cơn thịnh nộ","e":"The villagers expressed their wrath when they learned about the unfair treatment.","ev":"Người dân đã bày tỏ sự giận dữ khi biết về sự đối xử bất công.","k":"wrath"},{"t":"alacrity","p":"noun","d":"Sự nhanh nhẹn","e":"She accepted the challenge with alacrity, eager to prove herself.","ev":"Cô chấp nhận thử thách một cách nhanh chóng, háo hức để chứng tỏ bản thân.","k":"alacrity"},{"t":"dormant","p":"adjective","d":"Ngủ đông","e":"The seeds remained dormant until the spring rains woke them up.","ev":"Hạt giống vẫn nằm im cho đến khi mưa xuân đánh thức chúng.","k":"dormant"},{"t":"ebullient","p":"adjective","d":"Năng nổ","e":"His ebullient personality made him popular among his peers.","ev":"Tính cách sôi nổi của anh đã khiến anh được yêu mến trong nhóm bạn.","k":"ebullient"},{"t":"equanimity","p":"noun","d":"Bình tĩnh","e":"She maintained her equanimity during the crisis, making rational decisions.","ev":"Cô giữ được sự điềm tĩnh trong cuộc khủng hoảng, đưa ra những quyết định hợp lý.","k":"equanimity"},{"t":"hardy","p":"adjective","d":"Dẻo dai","e":"The hardy plants thrived in the harsh environment.","ev":"Những cây cối bền bỉ đã phát triển mạnh mẽ trong môi trường khắc nghiệt.","k":"hardy"},{"t":"indolent","p":"adjective","d":"Lười biếng","e":"His indolent attitude towards work led to poor performance.","ev":"Thái độ lười biếng của anh đối với công việc đã dẫn đến hiệu suất kém.","k":"indolent"},{"t":"insipid","p":"adjective","d":"Vô vị","e":"The soup was insipid, lacking flavor and excitement.","ev":"Món súp nhạt nhẽo, thiếu hương vị và sự thú vị.","k":"insipid"},{"t":"instigate","p":"verb","d":"Xúi giục","e":"The manager decided to instigate changes in the company culture to improve morale.","ev":"Người quản lý quyết định khởi xướng thay đổi trong văn hóa công ty để cải thiện tinh thần.","k":"instigate"},{"t":"invoke","p":"verb","d":"Kêu gọi, cầu khẩn","e":"She tried to invoke the spirit of teamwork in her colleagues during the project.","ev":"Cô cố gắng khơi dậy tinh thần đồng đội trong các đồng nghiệp của mình trong suốt dự án.","k":"invoke"},{"t":"lackadaisical","p":"adjective","d":"Lơ đãng","e":"His lackadaisical approach to studying resulted in low grades.","ev":"Cách tiếp cận thiếu quyết tâm của anh đối với việc học đã dẫn đến điểm số thấp.","k":"lackadaisical"},{"t":"laggard","p":"noun/adjective","d":"Người chậm chạp","e":"The laggard student finally turned in his assignment after much delay.","ev":"Sinh viên chậm chạp cuối cùng cũng đã nộp bài tập của mình sau nhiều lần trì hoãn.","k":"laggard"},{"t":"languid","p":"adjective","d":"Mệt mỏi","e":"She moved with a languid grace, as if she were floating through the room.","ev":"Cô di chuyển với sự duyên dáng uể oải, như thể đang trôi lơ lửng trong phòng.","k":"languid"}]},{"n":"Buổi 6","c":[{"t":"listless","p":"adjective","d":"Không có sức sống","e":"She felt listless and uninspired after a long week of work.","ev":"Cô cảm thấy uể oải và không có cảm hứng sau một tuần làm việc dài.","k":"listless"},{"t":"lull","p":"noun/verb","d":"Làm dịu","e":"The gentle lull of the waves made him feel relaxed and at peace.","ev":"Âm thanh nhẹ nhàng của sóng khiến anh cảm thấy thư giãn và bình yên.","k":"lull"},{"t":"pacify","p":"verb","d":"Xoa dịu","e":"He tried to pacify the angry crowd with a sincere apology.","ev":"Anh cố gắng làm dịu lòng đám đông giận dữ bằng một lời xin lỗi chân thành.","k":"pacify"},{"t":"placate","p":"verb","d":"Làm nguôi ngoai","e":"She offered a small gift to placate her friend after their argument.","ev":"Cô đã tặng một món quà nhỏ để xoa dịu người bạn của mình sau cuộc tranh cãi.","k":"placate"},{"t":"placid","p":"adjective","d":"Điềm tĩnh","e":"The placid lake reflected the clear blue sky perfectly.","ev":"Hồ nước yên tĩnh phản chiếu bầu trời xanh trong một cách hoàn hảo.","k":"placid"},{"t":"raucous","p":"adjective","d":"Ồn ào","e":"The raucous laughter from the party next door kept him awake all night.","ev":"Tiếng cười ồn ào từ bữa tiệc bên cạnh đã khiến anh không ngủ được suốt đêm.","k":"raucous"},{"t":"rouse, rousing","p":"verb/adjective","d":"Kích thích, gây hứng khởi","e":"The coach's speech was meant to rouse the team's spirit before the big game.","ev":"Bài phát biểu của huấn luyện viên nhằm khơi dậy tinh thần của đội trước trận đấu lớn.","k":"rouse, rousing"},{"t":"scintillating","p":"adjective","d":"Lấp lánh, hấp dẫn","e":"The scintillating conversation at dinner made the evening enjoyable.","ev":"Cuộc trò chuyện sáng tạo trong bữa tối đã làm cho buổi tối trở nên thú vị.","k":"scintillating"},{"t":"stagnant, \nstagnation","p":"adjective/noun","d":"Đình trệ, sự đình trệ","e":"The stagnant water in the pond was a breeding ground for mosquitoes.","ev":"Nước đọng trong ao là môi trường sinh sản cho muỗi.","k":"stagnant, stagnation"},{"t":"static (adjective)","p":"adjective","d":"Tĩnh","e":"The static atmosphere in the room made everyone feel uncomfortable.","ev":"Bầu không khí tĩnh lặng trong phòng khiến mọi người cảm thấy không thoải mái.","k":"static (adjective)"},{"t":"torpor","p":"noun","d":"Sự uể oải","e":"After a long period of torpor, she finally motivated herself to exercise again.","ev":"Sau một thời gian dài uể oải, cô đã tự thúc đẩy mình tập thể dục trở lại.","k":"torpor"},{"t":"unruly","p":"adjective","d":"Bất trị","e":"The unruly children made it difficult for the teacher to maintain order in the classroom.","ev":"Những đứa trẻ hỗn loạn đã khiến giáo viên khó giữ trật tự trong lớp học.","k":"unruly"},{"t":"vapid","p":"adjective","d":"Nhạt nhẽo","e":"The vapid conversation left her feeling bored and uninterested.","ev":"Cuộc trò chuyện nhạt nhẽo đã khiến cô cảm thấy chán nản và không hứng thú.","k":"vapid"},{"t":"abhor, abhorrence","p":"verb/noun","d":"Ghê tởm, sự ghê tởm","e":"He abhors cruelty to animals and advocates for their protection.","ev":"Anh ấy ghê tởm sự tàn ác đối với động vật và ủng hộ việc bảo vệ chúng.","k":"abhor, abhorrence"},{"t":"acrimony","p":"noun","d":"Sự châm chọc","e":"The acrimony between the two rivals was evident during the debate.","ev":"Sự cay đắng giữa hai đối thủ đã rõ ràng trong suốt cuộc tranh luận.","k":"acrimony"},{"t":"amiable","p":"adjective","d":"Tốt bụng","e":"She has an amiable personality, making her easy to get along with.","ev":"Cô ấy có tính cách thân thiện, khiến mọi người dễ dàng hòa hợp với cô.","k":"amiable"},{"t":"amicable","p":"adjective","d":"Thân thiện","e":"The two parties reached an amicable agreement after long negotiations.","ev":"Hai bên đã đạt được thỏa thuận thân thiện sau nhiều cuộc đàm phán dài.","k":"amicable"},{"t":"antipathy","p":"noun","d":"Sự ác cảm","e":"His antipathy toward the new policy was clear in his comments.","ev":"Sự chống đối của anh đối với chính sách mới đã rõ ràng trong những nhận xét của anh.","k":"antipathy"},{"t":"congenial","p":"adjective","d":"Thân thiện","e":"The congenial atmosphere at the gathering made everyone feel comfortable.","ev":"Bầu không khí thân thiện trong buổi gặp gỡ khiến mọi người cảm thấy thoải mái.","k":"congenial"},{"t":"disputatious","p":"adjective","d":"Thích tranh luận","e":"Her disputatious nature often led to arguments with her colleagues.","ev":"Tính cách thích tranh cãi của cô thường dẫn đến những cuộc cãi vã với đồng nghiệp.","k":"disputatious"}]},{"n":"Buổi 7","c":[{"t":"distaste","p":"noun","d":"Sự không ưa","e":"She felt a deep distaste for dishonesty in any form.","ev":"Cô cảm thấy sự ghê tởm sâu sắc đối với sự không trung thực dưới bất kỳ hình thức nào.","k":"distaste"},{"t":"empathetic, \nempathy","p":"adjective/noun","d":"Đồng cảm, sự đồng cảm","e":"His empathetic nature allowed him to connect with others easily.","ev":"Tính cách đồng cảm của anh giúp anh dễ dàng kết nối với người khác.","k":"empathetic, empathy"},{"t":"estrange, \nestrangement","p":"verb/noun","d":"Xa cách, sự xa cách","e":"The estrangement between the siblings was painful to witness.","ev":"Sự xa cách giữa các anh chị em thật đau lòng khi chứng kiến.","k":"estrange, estrangement"},{"t":"exacting","p":"adjective","d":"Khắt khe","e":"The project was exacting and required a lot of attention to detail.","ev":"Dự án này đòi hỏi sự chính xác và cần nhiều sự chú ý đến từng chi tiết.","k":"exacting"},{"t":"genial","p":"adjective","d":"Thân thiện","e":"His genial smile made everyone feel welcome at the party.","ev":"Nụ cười thân thiện của anh khiến mọi người cảm thấy được chào đón tại bữa tiệc.","k":"genial"},{"t":"officious","p":"adjective","d":"Quá nhiệt tình","e":"The officious assistant was always trying to tell others what to do.","ev":"Trợ lý quá tự mãn luôn cố gắng chỉ dẫn người khác phải làm gì.","k":"officious"},{"t":"parody","p":"noun/verb","d":"Nhại lại","e":"The comedian’s parody of the politician had everyone laughing.","ev":"Màn parodie của diễn viên hài về chính trị gia đã khiến mọi người cười ngả nghiêng.","k":"parody"},{"t":"rancor(ous)","p":"noun/adjective","d":"Sự hận thù, cay đắng","e":"There was rancor in his voice as he spoke about his former colleague.","ev":"Có sự cay đắng trong giọng nói của anh khi anh nói về người đồng nghiệp cũ.","k":"rancor(ous)"},{"t":"rapport","p":"noun","d":"Mối quan hệ","e":"They quickly developed a strong rapport through their shared interests.","ev":"Họ nhanh chóng phát triển được một mối quan hệ tốt đẹp nhờ những sở thích chung.","k":"rapport"},{"t":"recluse, reclusive","p":"noun/adjective","d":"Người sống ẩn dật, sống ẩn","e":"He lived as a recluse, rarely leaving his home or interacting with others.","ev":"Anh sống như một người ẩn dật, hiếm khi rời khỏi nhà hoặc giao tiếp với người khác.","k":"recluse, reclusive"},{"t":"satire, satirical, \nsatirize","p":"noun/adjective/verb","d":"Châm biếm, châm biếm, đả kích","e":"The book is a satire that critiques societal norms with humor.","ev":"Cuốn sách là một tác phẩm châm biếm chỉ trích các quy tắc xã hội bằng sự hài hước.","k":"satire, satirical, satirize"},{"t":"solicitous(ness)","p":"adj/noun","d":"Lo lắng, sự lo lắng","e":"She was solicitous about her friend’s well-being after the accident.","ev":"Cô đã rất quan tâm đến sức khỏe của bạn mình sau vụ tai nạn.","k":"solicitous(ness)"},{"t":"unwitting","p":"adjective","d":"Vô tình","e":"The unwitting participant had no idea what was about to happen.","ev":"Người tham gia không hay biết đã không biết điều gì sắp xảy ra.","k":"unwitting"},{"t":"amenable","p":"adjective","d":"Sẵn sàng hợp tác","e":"He is amenable to new ideas and always open to suggestions.","ev":"Anh ấy dễ tiếp thu các ý tưởng mới và luôn sẵn sàng lắng nghe những gợi ý.","k":"amenable"},{"t":"aspire","p":"verb","d":"Khao khát","e":"She aspires to become a successful artist one day.","ev":"Cô khao khát trở thành một nghệ sĩ thành công trong một ngày không xa.","k":"aspire"},{"t":"assiduous","p":"adjective","d":"Chăm chỉ","e":"His assiduous efforts in studying paid off with high grades.","ev":"Nỗ lực chăm chỉ của anh trong việc học đã được đền đáp bằng điểm số cao.","k":"assiduous"},{"t":"assuage","p":"verb","d":"Xoa dịu","e":"She tried to assuage his fears about the upcoming exam.","ev":"Cô cố gắng làm dịu nỗi lo lắng của anh về kỳ thi sắp tới.","k":"assuage"},{"t":"compliant, \ncompliance","p":"adj/noun","d":"Tuân thủ, sự tuân thủ","e":"Her compliant nature made her easy to work with, as she was always agreeable.","ev":"Tính cách dễ bảo của cô khiến việc làm việc cùng cô trở nên dễ dàng, vì cô luôn đồng thuận.","k":"compliant, compliance"},{"t":"dauntless","p":"adjective","d":"Không sợ hãi","e":"His dauntless spirit inspired others to face their fears.","ev":"Tinh thần không sợ hãi của anh đã truyền cảm hứng cho người khác đối mặt với nỗi sợ hãi của họ.","k":"dauntless"},{"t":"debacle","p":"noun","d":"Thất bại","e":"The debacle at the event led to a lot of negative publicity for the organization.","ev":"Cuộc khủng hoảng tại sự kiện đã dẫn đến nhiều tin tức tiêu cực cho tổ chức.","k":"debacle"}]},{"n":"Buổi 8","c":[{"t":"debilitate(d)","p":"verb/adjective","d":"Làm suy yếu","e":"The illness can debilitate even the strongest individuals.","ev":"Căn bệnh này có thể làm suy yếu ngay cả những người mạnh mẽ nhất.","k":"debilitate(d)"},{"t":"debunk","p":"verb/adjective","d":"Vạch trần","e":"The researcher aimed to debunk the myths surrounding the ancient artifact.","ev":"Nhà nghiên cứu nhằm mục đích vạch trần những huyền thoại xung quanh cổ vật cổ.","k":"debunk"},{"t":"deference, \ndeferential","p":"noun/adjective","d":"Tôn trọng, kính trọng","e":"He showed great deference to his elders during the ceremony.","ev":"Anh đã thể hiện sự tôn trọng lớn đối với những người lớn tuổi hơn trong buổi lễ.","k":"deference, deferential"},{"t":"deterrent","p":"noun/adjective","d":"Rào cản","e":"The new law was introduced as a deterrent against reckless driving.","ev":"Luật mới được giới thiệu như một biện pháp răn đe chống lại việc lái xe liều lĩnh.","k":"deterrent"},{"t":"disheartening","p":"adj","d":"Làm nản lòng","e":"The disheartening news about the project’s funding made the team anxious.","ev":"Tin tức khiến đội ngũ chán nản về việc tài trợ cho dự án đã khiến họ lo lắng.","k":"disheartening"},{"t":"dispel","p":"verb","d":"Xua tan","e":"She hoped to dispel the rumors by providing clear evidence.","ev":"Cô hy vọng có thể làm tan biến những tin đồn bằng cách cung cấp bằng chứng rõ ràng.","k":"dispel"},{"t":"disquiet(ing)","p":"verb/adjective","d":"Lo lắng, sự lo lắng","e":"The disquieting silence in the room suggested that something was wrong.","ev":"Sự im lặng đáng lo ngại trong phòng cho thấy có điều gì đó không ổn.","k":"disquiet(ing)"},{"t":"facile","p":"adj","d":"Dễ dàng, hời hợt","e":"His facile understanding of the topic impressed everyone in the meeting.","ev":"Sự hiểu biết dễ dàng của anh về chủ đề đã gây ấn tượng với mọi người trong cuộc họp.","k":"facile"},{"t":"futile, futility","p":"adj/n","d":"Vô ích, sự vô ích","e":"Their efforts to resolve the issue seemed futile in the face of such strong opposition.","ev":"Nỗ lực của họ để giải quyết vấn đề có vẻ vô nghĩa trước sự phản đối mạnh mẽ như vậy.","k":"futile, futility"},{"t":"gallant(ry)","p":"adj/n","d":"Dũng cảm, sự dũng cảm","e":"The gallant rescue of the trapped hikers was reported in the news.","ev":"Hành động dũng cảm cứu hộ những người leo núi bị mắc kẹt đã được đưa tin trên báo.","k":"gallant(ry)"},{"t":"impasse","p":"noun","d":"Ngõ cụt","e":"The negotiations reached an impasse, with neither side willing to compromise.","ev":"Các cuộc đàm phán đã đạt đến bế tắc, khi không bên nào sẵn sàng thỏa hiệp.","k":"impasse"},{"t":"indomitable","p":"adj","d":"Không thể bị khuất phục","e":"Her indomitable spirit helped her overcome numerous obstacles in life.","ev":"Tinh thần bất khuất của cô đã giúp cô vượt qua nhiều trở ngại trong cuộc sống.","k":"indomitable"},{"t":"intrepid","p":"adj","d":"Dũng cảm","e":"The intrepid explorer ventured into the uncharted territory with confidence.","ev":"Nhà thám hiểm dũng cảm đã mạo hiểm vào lãnh thổ chưa được bản đồ với sự tự tin.","k":"intrepid"},{"t":"onerous","p":"adj","d":"Nặng nề","e":"The onerous task required a significant amount of time and effort.","ev":"Nhiệm vụ nặng nề yêu cầu một lượng lớn thời gian và công sức.","k":"onerous"},{"t":"servile","p":"adj","d":"Phục tùng","e":"His servile attitude towards his boss was obvious to everyone in the office.","ev":"Thái độ phục tùng của anh đối với sếp đã rõ ràng với mọi người trong văn phòng.","k":"servile"},{"t":"steadfast","p":"adj","d":"Kiên định","e":"She remained steadfast in her beliefs, even when challenged.","ev":"Cô giữ vững niềm tin của mình, ngay cả khi bị thách thức.","k":"steadfast"},{"t":"subservient","p":"adj","d":"Phục tùng","e":"He took a subservient role in the project, always putting others' needs first.","ev":"Anh đảm nhận một vai trò phụ thuộc trong dự án, luôn đặt nhu cầu của người khác lên hàng đầu.","k":"subservient"},{"t":"tenacious, tenacity","p":"adj/n","d":"Kiên trì, sự kiên trì","e":"Her tenacious efforts to improve her skills eventually paid off.","ev":"Nỗ lực kiên trì của cô để cải thiện kỹ năng cuối cùng đã được đền đáp.","k":"tenacious, tenacity"},{"t":"tenuous","p":"adj","d":"Mỏng manh","e":"The connection between the two theories is quite tenuous and needs further investigation.","ev":"Mối liên hệ giữa hai lý thuyết này khá mong manh và cần được điều tra thêm.","k":"tenuous"},{"t":"tribulation","p":"noun","d":"Khó khăn","e":"They faced many tribulations during their journey but persevered through them all.","ev":"Họ đã phải đối mặt với nhiều thử thách trong suốt hành trình nhưng đã kiên trì vượt qua tất cả.","k":"tribulation"}]},{"n":"Buổi 9","c":[{"t":"vying","p":"verb","d":"Cạnh tranh","e":"The two companies are vying for the top position in the market.","ev":"Hai công ty đang cạnh tranh để giành vị trí hàng đầu trên thị trường.","k":"vying"},{"t":"acumen","p":"noun","d":"Sự nhạy bén","e":"Her business acumen helped her make successful investments.","ev":"Khả năng nhạy bén trong kinh doanh của cô đã giúp cô thực hiện những khoản đầu tư thành công.","k":"acumen"},{"t":"adept","p":"adj","d":"Thạo","e":"He is adept at solving complex mathematical problems quickly.","ev":"Anh ấy rất giỏi trong việc giải quyết nhanh chóng các bài toán phức tạp.","k":"adept"},{"t":"adroit","p":"adj","d":"Khéo léo","e":"She is adroit at negotiating and often gets the best deals.","ev":"Cô rất khéo léo trong việc đàm phán và thường có được những thỏa thuận tốt nhất.","k":"adroit"},{"t":"anthropology","p":"noun","d":"Nhân chủng học","e":"Anthropology provides insights into human behavior and culture.","ev":"Nhân học cung cấp những hiểu biết về hành vi và văn hóa của con người.","k":"anthropology"},{"t":"boorish, \nboorishness","p":"noun","d":"Thô lỗ, sự thô lỗ","e":"His boorish behavior at the dinner party embarrassed everyone.","ev":"Hành vi thô lỗ của anh ấy tại bữa tiệc tối đã làm xấu hổ mọi người.","k":"boorish, boorishness"},{"t":"cerebral","p":"adj","d":"Thuộc về trí óc","e":"The cerebral nature of the discussion made it challenging for some to keep up.","ev":"Tính trí thức của cuộc thảo luận khiến một số người khó theo kịp.","k":"cerebral"},{"t":"churlish","p":"adj","d":"Thô lỗ","e":"His churlish remarks during the meeting alienated his colleagues.","ev":"Những nhận xét thô lỗ của anh trong cuộc họp đã làm xa lánh đồng nghiệp.","k":"churlish"},{"t":"conscientious","p":"adj","d":"Tận tâm","e":"She is a conscientious worker who pays attention to every detail.","ev":"Cô là một nhân viên tận tâm, luôn chú ý đến từng chi tiết.","k":"conscientious"},{"t":"cosmopolitan","p":"adj","d":"Quốc tế","e":"The cosmopolitan city attracts people from all over the world.","ev":"Thành phố quốc tế thu hút người từ khắp nơi trên thế giới.","k":"cosmopolitan"},{"t":"credulity, \ncredulous","p":"noun","d":"Dễ tin, sự dễ tin","e":"His credulity made him an easy target for scams and fraud.","ev":"Sự cả tin của anh khiến anh trở thành mục tiêu dễ dàng cho những vụ lừa đảo.","k":"credulity, credulous"},{"t":"didactic","p":"adj","d":"Mang tính giảng dạy","e":"The didactic nature of the lecture made it both informative and engaging.","ev":"Tính giáo dục của bài giảng khiến nó vừa cung cấp thông tin vừa hấp dẫn.","k":"didactic"},{"t":"discern, discerning","p":"verb","d":"Nhận thức, sự nhận thức","e":"She could discern the subtle differences between the two paintings.","ev":"Cô có thể nhận biết những khác biệt tinh tế giữa hai bức tranh.","k":"discern, discerning"},{"t":"epiphany","p":"noun","d":"Sự hiện ra rõ ràng","e":"His epiphany about life changed his perspective completely.","ev":"Sự khai sáng về cuộc sống của anh đã thay đổi hoàn toàn quan điểm của anh.","k":"epiphany"},{"t":"erudite, erudition","p":"noun","d":"Học thức, sự học thức","e":"The erudite professor captivated the students with his extensive knowledge.","ev":"Giáo sư uyên bác đã thu hút sinh viên bằng kiến thức phong phú của mình.","k":"erudite, erudition"},{"t":"esoteric","p":"adj","d":"Bí truyền","e":"The esoteric nature of the topic made it difficult for outsiders to understand.","ev":"Tính chất bí truyền của chủ đề khiến người ngoài khó hiểu.","k":"esoteric"},{"t":"fastidious","p":"adj","d":"Kén chọn","e":"She is fastidious about cleanliness and organizes everything meticulously.","ev":"Cô rất cầu toàn về sự sạch sẽ và sắp xếp mọi thứ một cách tỉ mỉ.","k":"fastidious"},{"t":"finesse","p":"noun/verb","d":"Sự khéo léo","e":"He handled the situation with finesse, ensuring a smooth resolution.","ev":"Anh đã xử lý tình huống một cách khéo léo, đảm bảo giải quyết suôn sẻ.","k":"finesse"},{"t":"flummox","p":"verb","d":"Làm bối rối","e":"The unexpected question flummoxed him, leaving him speechless.","ev":"Câu hỏi bất ngờ đã khiến anh bối rối, để lại anh trong trạng thái câm lặng.","k":"flummox"},{"t":"folly","p":"noun","d":"Sự ngu dốt","e":"It was sheer folly to invest all her savings in a single venture.","ev":"Đó là sự ngu dốt khi đầu tư tất cả tiền tiết kiệm của cô vào một dự án duy nhất.","k":"folly"}]},{"n":"Buổi 10","c":[{"t":"foolhardy","p":"adj","d":"Liều lĩnh","e":"It was foolhardy to attempt such a dangerous climb without proper equipment.","ev":"Thật ngu ngốc khi cố gắng leo núi nguy hiểm như vậy mà không có thiết bị thích hợp.","k":"foolhardy"},{"t":"grandiose","p":"adj","d":"Hào nhoáng","e":"His grandiose plans for the project were met with skepticism from the team.","ev":"Những kế hoạch phức tạp của anh cho dự án đã gặp sự hoài nghi từ đội ngũ.","k":"grandiose"},{"t":"inane","p":"adj","d":"Vô nghĩa","e":"The inane comments during the meeting only distracted everyone from the main issue.","ev":"Những bình luận vô nghĩa trong cuộc họp chỉ khiến mọi người phân tâm khỏi vấn đề chính.","k":"inane"},{"t":"ineptitude","p":"noun","d":"Sự vụng về","e":"His ineptitude in handling the situation caused further complications.","ev":"Sự bất tài của anh trong việc xử lý tình huống đã gây ra những phức tạp thêm.","k":"ineptitude"},{"t":"ingenuous","p":"adj","d":"Ngây thơ","e":"She has an ingenuous charm that makes her very likable.","ev":"Cô ấy có một sức hấp dẫn ngây thơ khiến cô rất được yêu mến.","k":"ingenuous"},{"t":"lithe","p":"adj","d":"Dẻo dai","e":"The dancer moved with a lithe grace that captivated the audience.","ev":"Vũ công di chuyển với sự duyên dáng mềm mại đã thu hút khán giả.","k":"lithe"},{"t":"neophyte","p":"noun","d":"Người mới bắt đầu","e":"As a neophyte in the industry, he had much to learn from his experienced colleagues.","ev":"Là một người mới trong ngành, anh có nhiều điều cần học hỏi từ các đồng nghiệp có kinh nghiệm.","k":"neophyte"},{"t":"oversight","p":"noun","d":"Sự giám sát","e":"The oversight in the report led to significant errors in the final analysis.","ev":"Sự bỏ sót trong báo cáo đã dẫn đến những sai sót lớn trong phân tích cuối cùng.","k":"oversight"},{"t":"painstaking","p":"adj","d":"Cần cù","e":"Her painstaking attention to detail made her an excellent editor.","ev":"Sự chú ý tỉ mỉ đến từng chi tiết của cô đã làm cho cô trở thành một biên tập viên xuất sắc.","k":"painstaking"},{"t":"pedant, pedantic, pedantry","p":"noun","d":"Người câu nệ, sự câu nệ","e":"He was criticized for his pedantic approach to teaching, focusing too much on minor details.","ev":"Anh bị chỉ trích vì cách dạy học chú trọng quá nhiều vào những chi tiết nhỏ.","k":"pedant, pedantic, pedantry"},{"t":"precocious","p":"adj","d":"Sớm phát triển","e":"The precocious child amazed everyone with her advanced vocabulary.","ev":"Cô bé thông minh khiến mọi người kinh ngạc với vốn từ vựng phát triển vượt trội.","k":"precocious"},{"t":"provincial","p":"adj","d":"Thuộc về tỉnh lẻ","e":"His provincial mindset made it difficult for him to understand broader perspectives.","ev":"Tư duy tỉnh lẻ của anh khiến anh khó hiểu được những quan điểm rộng hơn.","k":"provincial"},{"t":"punctilious","p":"adj","d":"Cẩn thận","e":"She was punctilious about following the rules, ensuring everything was done correctly.","ev":"Cô rất chú ý đến việc tuân theo các quy tắc, đảm bảo mọi thứ đều được thực hiện chính xác.","k":"punctilious"},{"t":"pundit","p":"noun","d":"Chuyên gia","e":"The pundit offered insightful commentary on the political situation.","ev":"Chuyên gia đã đưa ra những nhận xét sâu sắc về tình hình chính trị.","k":"pundit"},{"t":"quixotic","p":"adj","d":"Mơ mộng","e":"His quixotic dreams of becoming a famous artist often distracted him from reality.","ev":"Những giấc mơ hão huyền của anh về việc trở thành một nghệ sĩ nổi tiếng thường khiến anh lạc lối khỏi thực tế.","k":"quixotic"},{"t":"sage","p":"noun","d":"Người khôn ngoan","e":"The sage shared his wisdom with those who sought guidance.","ev":"Nhà hiền triết đã chia sẻ trí tuệ của mình với những người tìm kiếm sự hướng dẫn.","k":"sage"},{"t":"scrupulous","p":"adj","d":"Cẩn thận","e":"She was scrupulous in her research, ensuring all data was accurate and reliable.","ev":"Cô rất cẩn trọng trong nghiên cứu của mình, đảm bảo tất cả dữ liệu đều chính xác và đáng tin cậy.","k":"scrupulous"},{"t":"shrewd","p":"adj","d":"Sắc sảo","e":"His shrewd investment decisions greatly increased his wealth.","ev":"Các quyết định đầu tư khôn ngoan của anh đã làm gia tăng đáng kể sự giàu có của mình.","k":"shrewd"},{"t":"slipshod","p":"adj","d":"Cẩu thả","e":"She complained that the carpenter's work had been slipshod.","ev":"Cô ấy phàn nàn rằng sản phẩm của người thợ mộc thật cẩu thả","k":"slipshod"},{"t":"stupefy, \nstupefaction","p":"verb/noun","d":"Làm sửng sốt, sự sửng sốt","e":"The magician's performance left the audience in a state of stupefaction.","ev":"Màn trình diễn của ảo thuật gia đã khiến khán giả rơi vào trạng thái choáng váng.","k":"stupefy, stupefaction"}]},{"n":"Buổi 11","c":[{"t":"susceptible","p":"adj","d":"Dễ bị ảnh hưởng","e":"Children are often more susceptible to illnesses than adults.","ev":"Trẻ em thường dễ bị bệnh hơn người lớn.","k":"susceptible"},{"t":"tractable","p":"adj","d":"Dễ quản lý","e":"The dog was surprisingly tractable, following every command without hesitation.","ev":"Chú chó thật bất ngờ khi rất dễ bảo, nghe theo mọi lệnh mà không do dự.","k":"tractable"},{"t":"uncanny","p":"adj","d":"Kỳ lạ","e":"There was an uncanny resemblance between the two sisters, almost as if they were twins.","ev":"Có một sự tương đồng kỳ lạ giữa hai chị em, gần như họ là sinh đôi.","k":"uncanny"},{"t":"uncouth","p":"adj","d":"Thô lỗ","e":"His uncouth behavior at the formal dinner shocked the guests.","ev":"Hành vi thô lỗ của anh tại bữa tối trang trọng đã làm cho các vị khách sốc.","k":"uncouth"},{"t":"unfathomable","p":"adj","d":"Không thể hiểu được","e":"The depths of the ocean remain largely unfathomable to scientists.","ev":"Độ sâu của đại dương vẫn chủ yếu không thể hiểu được đối với các nhà khoa học.","k":"unfathomable"},{"t":"ungainly","p":"adj","d":"Kỳ quặc","e":"The ungainly teenager tripped over his own feet while walking.","ev":"Cậu thanh niên vụng về đã vấp ngã vì chính đôi chân của mình khi đi bộ.","k":"ungainly"},{"t":"urbane","p":"adj","d":"Thanh lịch","e":"His urbane manner made him popular among his peers at the social event.","ev":"Cách cư xử lịch thiệp của anh khiến anh trở nên nổi bật trong mắt bạn bè tại sự kiện xã hội.","k":"urbane"},{"t":"venerable","p":"adj","d":"Đáng kính","e":"The venerable professor was respected by all his students for his wisdom.","ev":"Giáo sư uy tín được tất cả sinh viên tôn trọng vì trí tuệ của ông.","k":"venerable"},{"t":"virtuoso, virtuosity","p":"noun","d":"Nghệ sĩ tài ba, sự tài","e":"The young musician displayed virtuosity beyond his years during the performance.","ev":"Nhạc sĩ trẻ đã thể hiện tài năng vượt trội hơn cả tuổi của mình trong buổi biểu diễn.","k":"virtuoso, virtuosity"},{"t":"wry","p":"adj","d":"Mỉa mai","e":"She gave a wry smile when she heard the ironic comment.","ev":"Cô mỉm cười châm biếm khi nghe nhận xét châm biếm.","k":"wry"},{"t":"corroborate","p":"verb","d":"Xác nhận","e":"The witness was called to corroborate the evidence presented in court.","ev":"Nhân chứng đã được mời đến để xác nhận bằng chứng được trình bày tại tòa.","k":"corroborate"},{"t":"decorum, decorous","p":"noun","d":"Lịch sự, sự lịch sự","e":"The decorum maintained at the event was impressive, with everyone behaving appropriately.","ev":"Sự lịch thiệp được duy trì tại sự kiện thật ấn tượng, với mọi người cư xử đúng mực.","k":"decorum, decorous"},{"t":"equitable","p":"adj","d":"Công bằng","e":"The judge aimed to ensure an equitable distribution of resources among the community.","ev":"Thẩm phán nhắm đến việc đảm bảo phân phối công bằng tài nguyên giữa các thành viên trong cộng đồng.","k":"equitable"},{"t":"illicit","p":"adj","d":"Bất hợp pháp","e":"The illicit trade in endangered species is a serious global issue.","ev":"Thương mại bất hợp pháp về các loài có nguy cơ tuyệt chủng là một vấn đề toàn cầu nghiêm trọng.","k":"illicit"},{"t":"incriminate","p":"verb","d":"Kết tội","e":"The evidence seemed to incriminate him, making the case against him stronger.","ev":"Bằng chứng dường như buộc tội anh, làm cho vụ án chống lại anh trở nên mạnh mẽ hơn.","k":"incriminate"},{"t":"indict(ment)","p":"verb/noun","d":"Buộc tội, sự buộc tội","e":"The indictment accused him of multiple counts of fraud.","ev":"Cáo trạng buộc tội anh về nhiều tội danh gian lận.","k":"indict(ment)"},{"t":"indignant","p":"adj","d":"Phẫn nộ","e":"She felt indignant at the unfair treatment she received from her boss.","ev":"Cô cảm thấy phẫn nộ trước sự đối xử bất công mà cô nhận được từ sếp.","k":"indignant"},{"t":"indulgent","p":"adj","d":"Dễ dãi","e":"The indulgent parents often spoiled their children with extravagant gifts.","ev":"Các bậc phụ huynh nuông chiều thường làm hư con cái mình bằng những món quà xa xỉ.","k":"indulgent"},{"t":"judicious","p":"adj","d":"Sáng suốt","e":"His judicious decision helped the company avoid a major crisis.","ev":"Quyết định khôn ngoan của anh đã giúp công ty tránh được một cuộc khủng hoảng lớn.","k":"judicious"},{"t":"ratify","p":"verb","d":"Phê chuẩn","e":"The treaty must be ratified by both countries before it takes effect.","ev":"Hiệp ước phải được cả hai quốc gia phê chuẩn trước khi có hiệu lực.","k":"ratify"}]},{"n":"Buổi 12","c":[{"t":"sanction","p":"verb","d":"Phê chuẩn","e":"The government decided to sanction the new regulations to improve safety standards.","ev":"Chính phủ quyết định phê chuẩn các quy định mới để cải thiện tiêu chuẩn an toàn.","k":"sanction"},{"t":"vindicate, \nvindication","p":"verb/noun","d":"Biện hộ, sự biện hộ","e":"The evidence helped to vindicate her after the allegations were made.","ev":"Bằng chứng đã giúp biện minh cho cô sau khi có những cáo buộc được đưa ra.","k":"vindicate, vindication"},{"t":"altruistic, altruism","p":"adj","d":"Vị tha, sự vị tha","e":"His altruistic behavior showed a genuine concern for the well-being of others.","ev":"Hành vi vị tha của anh thể hiện sự quan tâm chân thành đến sự phúc lợi của người khác.","k":"altruistic, altruism"},{"t":"avarice","p":"noun","d":"Tham lam","e":"Avarice often leads to unethical behavior in business.","ev":"Lòng tham thường dẫn đến hành vi phi đạo đức trong kinh doanh.","k":"avarice"},{"t":"benevolent","p":"noun","d":"Nhân từ","e":"The benevolent organization provides food and shelter for the homeless.","ev":"Tổ chức nhân đạo cung cấp thực phẩm và chỗ ở cho những người vô gia cư.","k":"benevolent"},{"t":"bequeath","p":"verb","d":"Để lại (thừa kế)","e":"She decided to bequeath her entire estate to her favorite charity.","ev":"Cô quyết định để lại toàn bộ tài sản của mình cho tổ chức từ thiện mà cô yêu thích.","k":"bequeath"},{"t":"depreciation, \ndepreciatory","p":"noun","d":"Sự giảm giá trị","e":"The depreciation of the currency has affected the economy negatively.","ev":"Sự giảm giá của đồng tiền đã ảnh hưởng tiêu cực đến nền kinh tế.","k":"depreciation, depreciatory"},{"t":"destitute","p":"noun","d":"Thiếu thốn","e":"Many families are destitute and struggle to meet their basic needs.","ev":"Nhiều gia đình sống trong cảnh nghèo đói và vật lộn để đáp ứng nhu cầu cơ bản.","k":"destitute"},{"t":"exorbitant","p":"adj","d":"Cắt cổ, quá cao","e":"The exorbitant prices of luxury goods can deter many consumers.","ev":"Giá cả quá cao của hàng hóa xa xỉ có thể làm nhiều người tiêu dùng chùn bước.","k":"exorbitant"},{"t":"frugal(ity)","p":"adj","d":"Tiết kiệm, sự tiết kiệm","e":"He lived a frugal lifestyle, saving money wherever he could.","ev":"Anh sống một cuộc sống tiết kiệm, tiết kiệm tiền bất cứ khi nào có thể.","k":"frugal(ity)"},{"t":"lucrative","p":"noun","d":"Có lợi","e":"The new startup proved to be a lucrative venture for its founders.","ev":"Công ty khởi nghiệp mới đã chứng tỏ là một dự án sinh lời cho các nhà sáng lập.","k":"lucrative"},{"t":"luxuriant","p":"adj","d":"Tươi tốt","e":"The luxuriant gardens were filled with exotic plants and flowers.","ev":"Những khu vườn tươi tốt đầy những loại cây và hoa kỳ lạ.","k":"luxuriant"},{"t":"magnanimity, \nmagnanimous","p":"adj/noun","d":"Khoan dung, sự khoan dung","e":"Her magnanimity in forgiving others made her well-respected in the community.","ev":"Tấm lòng rộng lượng của cô trong việc tha thứ cho người khác khiến cô được tôn trọng trong cộng đồng.","k":"magnanimity, magnanimous"},{"t":"mercenary","p":"noun","d":"Vụ lợi","e":"The mercenary soldier fought for whoever paid the highest wage.","ev":"Người lính đánh thuê chiến đấu cho bất cứ ai trả lương cao nhất.","k":"mercenary"},{"t":"miserly","p":"adj","d":"Keo kiệt","e":"His miserly habits kept him from enjoying life to the fullest.","ev":"Thói quen keo kiệt của anh đã ngăn cản anh tận hưởng cuộc sống một cách trọn vẹn.","k":"miserly"},{"t":"patronize","p":"verb","d":"Bảo trợ","e":"It’s not polite to patronize someone just because you think you know more than they do.","ev":"Không lịch sự khi hạ thấp ai đó chỉ vì bạn nghĩ rằng bạn biết nhiều hơn họ.","k":"patronize"},{"t":"penurious","p":"noun","d":"Nghèo khổ","e":"The penurious old man lived in a small, dilapidated house.","ev":"Người đàn ông nghèo khổ sống trong một ngôi nhà nhỏ và xuống cấp.","k":"penurious"},{"t":"perquisite","p":"noun","d":"Quyền lợi","e":"A company car is often considered a perquisite of the job.","ev":"Một chiếc xe công ty thường được coi là một đặc quyền của công việc.","k":"perquisite"},{"t":"philanthropist, \nphilanthropic","p":"adj/noun","d":"Nhà từ thiện, nhân đạo","e":"The philanthropist donated millions to support education and healthcare initiatives.","ev":"Nhà từ thiện đã quyên góp hàng triệu đô la để hỗ trợ các sáng kiến giáo dục và chăm sóc sức khỏe.","k":"philanthropist, philanthropic"},{"t":"procure","p":"verb","d":"Đạt được","e":"He worked hard to procure the necessary materials for the project.","ev":"Anh đã làm việc chăm chỉ để mua được những vật liệu cần thiết cho dự án.","k":"procure"}]},{"n":"Buổi 13","c":[{"t":"provident","p":"adj","d":"Lo xa","e":"She was provident enough to save money for her children’s education.","ev":"Cô đủ khôn ngoan để tiết kiệm tiền cho việc học của con cái.","k":"provident"},{"t":"squander","p":"verb","d":"Phung phí","e":"Don’t squander your time on trivial matters; focus on what truly matters.","ev":"Đừng lãng phí thời gian vào những điều tầm thường; hãy tập trung vào những gì thực sự quan trọng.","k":"squander"},{"t":"venal(ity)","p":"adj","d":"Có thể mua chuộc","e":"His venality was evident when he accepted bribes from several companies.","ev":"Tính tham nhũng của anh rõ ràng khi anh nhận hối lộ từ một số công ty.","k":"venal(ity)"},{"t":"vocation","p":"noun","d":"Nghề nghiệp","e":"Teaching was her true vocation, and she excelled at it.","ev":"Giảng dạy là ơn gọi thực sự của cô, và cô đã xuất sắc trong lĩnh vực này.","k":"vocation"},{"t":"aberration","p":"noun","d":"Sự lệch lạc","e":"The sudden change in his behavior was seen as an aberration by his friends.","ev":"Sự thay đổi đột ngột trong hành vi của anh được bạn bè coi là một sự lầm lạc.","k":"aberration"},{"t":"accost","p":"verb","d":"Tiếp cận","e":"He was accosted by a stranger asking for directions.","ev":"Anh bị một người lạ tiếp cận và hỏi đường.","k":"accost"},{"t":"adamant","p":"adj","d":"Kiên quyết","e":"She remained adamant about her decision to move forward with the project.","ev":"Cô kiên quyết về quyết định tiếp tục thực hiện dự án.","k":"adamant"},{"t":"apathetic, apathy","p":"adj/noun","d":"Thờ ơ, sự thờ ơ","e":"His apathetic response to the crisis surprised everyone.","ev":"Phản ứng thờ ơ của anh đối với cuộc khủng hoảng đã làm mọi người bất ngờ.","k":"apathetic, apathy"},{"t":"ascendancy","p":"noun","d":"Quyền lực","e":"The party regained ascendancy in the political landscape after the election.","ev":"Đảng đã lấy lại thế thượng phong trong bối cảnh chính trị sau cuộc bầu cử.","k":"ascendancy"},{"t":"ascetic, asceticism","p":"adj/noun","d":"Khổ hạnh, sự khổ hạnh","e":"The ascetic monk lived a life of simplicity and self-denial.","ev":"Nhà sư khổ hạnh sống một cuộc đời giản dị và từ chối bản thân.","k":"ascetic, asceticism"},{"t":"august","p":"adj","d":"Uy nghi","e":"The august ceremony was attended by dignitaries from around the world.","ev":"Buổi lễ uy nghi được tham dự bởi các nhân vật quan trọng từ khắp nơi trên thế giới.","k":"august"},{"t":"autocrat, autocratic","p":"noun","d":"Chuyên chế, nhà độc tài","e":"The autocrat ruled with an iron fist, leaving no room for dissent.","ev":"Nhà độc tài cai trị bằng bàn tay sắt, không để lại chỗ cho sự bất đồng.","k":"autocrat, autocratic"},{"t":"automaton","p":"noun","d":"Máy móc","e":"He moved through life like an automaton, going through the motions without passion.","ev":"Anh sống như một người máy, thực hiện mọi việc mà không có đam mê.","k":"automaton"},{"t":"banal","p":"verb","d":"Tầm thường","e":"The movie was criticized for its banal dialogue and predictable plot.","ev":"Bộ phim bị chỉ trích vì lời thoại tầm thường và cốt truyện dễ đoán.","k":"banal"},{"t":"bipartisanship","p":"noun","d":"Chính trị lưỡng đảng","e":"Bipartisanship is essential for passing significant legislation.","ev":"Sự hợp tác giữa hai đảng là cần thiết để thông qua các luật quan trọng.","k":"bipartisanship"},{"t":"depose","p":"verb","d":"Hạ bệ","e":"The council decided to depose the corrupt mayor after the investigation.","ev":"Hội đồng quyết định lật đổ thị trưởng tham nhũng sau cuộc điều tra.","k":"depose"},{"t":"derivative","p":"noun/adj","d":"Bắt nguồn từ","e":"His ideas were seen as derivative, lacking originality and depth.","ev":"Những ý tưởng của anh bị coi là không sáng tạo, thiếu tính độc đáo và chiều sâu.","k":"derivative"},{"t":"desecration","p":"noun","d":"Sự báng bổ","e":"The desecration of the historic site sparked outrage among the community.","ev":"Hành vi xúc phạm địa điểm lịch sử đã gây ra sự phẫn nộ trong cộng đồng.","k":"desecration"},{"t":"despot","p":"noun","d":"Nhà độc tài","e":"The despot ruled with fear and intimidation, suppressing any opposition.","ev":"Nhà chuyên chế cai trị bằng sự sợ hãi và đe dọa, đàn áp mọi sự phản đối.","k":"despot"},{"t":"doctrine","p":"noun","d":"Học thuyết","e":"The doctrine of equality is fundamental to the nation's constitution.","ev":"Học thuyết về bình đẳng là nền tảng của hiến pháp quốc gia.","k":"doctrine"}]},{"n":"Buổi 14","c":[{"t":"dogmatic","p":"adj","d":"Giáo điều","e":"His dogmatic beliefs often led to heated arguments with others.","ev":"Những niềm tin giáo điều của anh thường dẫn đến những cuộc tranh cãi gay gắt với người khác.","k":"dogmatic"},{"t":"eclectic","p":"adj","d":"Tinh chọn","e":"The eclectic menu featured dishes from various international cuisines.","ev":"Thực đơn đa dạng có nhiều món ăn từ các nền văn hóa ẩm thực quốc tế khác nhau.","k":"eclectic"},{"t":"egalitarian","p":"adj","d":"Bình đẳng","e":"The country promotes an egalitarian society where everyone has equal rights.","ev":"Quốc gia này thúc đẩy một xã hội bình đẳng nơi mọi người có quyền lợi như nhau.","k":"egalitarian"},{"t":"exhibitionist, \nexhibitionistic","p":"adj","d":"Người thích phô trương, tính phô","e":"His exhibitionist tendencies made him the center of attention at every party.","ev":"Xu hướng thích phô trương của anh khiến anh trở thành tâm điểm chú ý tại mỗi bữa tiệc.","k":"exhibitionist, exhibitionistic"},{"t":"faction","p":"noun","d":"Phái","e":"The faction within the party was pushing for more radical changes.","ev":"Nhóm phái trong đảng đang thúc đẩy những thay đổi quyết liệt hơn.","k":"faction"},{"t":"fanaticism","p":"noun","d":"Chủ nghĩa cuồng tín","e":"Fanaticism can lead to dangerous consequences in any ideology.","ev":"Sự cuồng tín có thể dẫn đến những hậu quả nguy hiểm trong bất kỳ hệ tư tưởng nào.","k":"fanaticism"},{"t":"hackneyed","p":"adj","d":"Cũ kỹ","e":"The movie was criticized for its hackneyed plot and clichéd characters.","ev":"Bộ phim bị chỉ trích vì cốt truyện tầm thường và các nhân vật rập khuôn.","k":"hackneyed"},{"t":"heresy, heretic","p":"noun","d":"Dị giáo, người dị giáo","e":"Accusing him of heresy, the church declared him a heretic and excommunicated him.","ev":"Buộc tội anh dị giáo, nhà thờ tuyên bố anh là người dị giáo và đã tước bỏ quyền giáo hội của anh.","k":"heresy, heretic"},{"t":"idiosyncracy, \nidiosyncratic","p":"noun/adj","d":"Tính cách riêng, thuộc về tính","e":"Her idiosyncrasy of collecting vintage postcards made her unique among her friends.","ev":"Thói quen kỳ quặc của cô trong việc thu thập bưu thiếp cổ điển khiến cô trở nên độc đáo trong số bạn bè.","k":"idiosyncracy, idiosyncratic"},{"t":"orthodox","p":"adj","d":"Chính thống","e":"His orthodox views on education often clashed with innovative teaching methods.","ev":"Quan điểm chính thống của ông về giáo dục thường mâu thuẫn với các phương pháp giảng dạy sáng tạo.","k":"orthodox"},{"t":"pacifist","p":"adj","d":"Người theo chủ nghĩa hòa bình","e":"As a pacifist, she strongly opposed the use of violence in any form.","ev":"Là một người theo chủ nghĩa hòa bình, cô mạnh mẽ phản đối việc sử dụng bạo lực dưới bất kỳ hình thức nào.","k":"pacifist"},{"t":"partisan","p":"noun","d":"Người theo đảng phái","e":"The partisan debates in the media often create division among the public.","ev":"Những cuộc tranh luận theo phe phái trong truyền thông thường tạo ra sự chia rẽ trong công chúng.","k":"partisan"},{"t":"piety, pious","p":"noun/adj","d":"Đạo đức, sùng đạo","e":"His piety was evident in his daily rituals and charitable acts.","ev":"Tấm lòng sùng đạo của anh rõ ràng qua những nghi lễ hàng ngày và các hành động từ thiện của anh.","k":"piety, pious"},{"t":"polemical","p":"noun","d":"Đấu tranh, tranh cãi","e":"The polemical article sparked controversy and debate in the academic community.","ev":"Bài viết gây tranh cãi đã kích thích sự tranh luận và tranh cãi trong cộng đồng học thuật.","k":"polemical"},{"t":"renounce","p":"verb","d":"Từ bỏ","e":"He chose to renounce his previous lifestyle and start anew.","ev":"Anh quyết định từ bỏ lối sống trước đây và bắt đầu lại.","k":"renounce"},{"t":"reverent","p":"adj","d":"Kính trọng","e":"She spoke in a reverent tone when discussing the contributions of the late professor.","ev":"Cô nói với tông giọng kính trọng khi thảo luận về những đóng góp của giáo sư đã qua đời.","k":"reverent"},{"t":"sanctity","p":"noun","d":"Sự thiêng liêng","e":"The sanctity of the ancient site was preserved by strict regulations.","ev":"Tính thiêng liêng của địa điểm cổ đại được bảo tồn bởi các quy định nghiêm ngặt.","k":"sanctity"},{"t":"staunch","p":"adj","d":"Trung thành","e":"He is a staunch supporter of environmental protection policies.","ev":"Anh là một người ủng hộ vững chắc cho các chính sách bảo vệ môi trường.","k":"staunch"},{"t":"stock (adjective)","p":"adj","d":"Thông dụng","e":"The stock response from the spokesperson lacked genuine insight into the issue.","ev":"Phản ứng theo mẫu từ người phát ngôn thiếu sự hiểu biết chân thật về vấn đề.","k":"stock (adjective)"},{"t":"strident","p":"adj","d":"Kích động","e":"Her strident voice could be heard above the noise of the crowd.","ev":"Giọng nói chói tai của cô có thể nghe thấy trên tiếng ồn của đám đông.","k":"strident"}]},{"n":"Buổi 15","c":[{"t":"subversive","p":"adj","d":"Lật đổ","e":"The subversive group aimed to undermine the government’s authority.","ev":"Nhóm nổi loạn nhằm mục đích làm suy yếu quyền lực của chính phủ.","k":"subversive"},{"t":"supplant","p":"verb","d":"Thay thế","e":"They hoped to supplant the old technology with something more efficient.","ev":"Họ hy vọng thay thế công nghệ cũ bằng một cái gì đó hiệu quả hơn.","k":"supplant"},{"t":"sycophant","p":"noun","d":"Kẻ nịnh bợ","e":"The sycophant always flatters his boss to gain favor.","ev":"Kẻ nịnh hót luôn tâng bốc sếp của mình để chiếm được cảm tình.","k":"sycophant"},{"t":"toady","p":"noun","d":"Kẻ nịnh bợ","e":"The toady followed his wealthy friend everywhere, hoping for financial gain.","ev":"Kẻ nịnh bợ luôn theo chân người bạn giàu có, hy vọng được lợi ích tài chính.","k":"toady"},{"t":"totalitarian","p":"noun","d":"Chuyên chế","e":"The totalitarian regime controlled every aspect of citizens’ lives.","ev":"Chế độ độc tài kiểm soát mọi khía cạnh trong cuộc sống của công dân.","k":"totalitarian"},{"t":"trite","p":"adj","d":"Cũ kỹ","e":"His jokes quickly became trite and lost their appeal.","ev":"Những câu đùa của anh nhanh chóng trở nên tầm thường và mất đi sức hấp dẫn.","k":"trite"},{"t":"usurp","p":"verb","d":"Cướp đoạt","e":"They tried to usurp power from the current leaders of the organization.","ev":"Họ đã cố gắng chiếm đoạt quyền lực từ các nhà lãnh đạo hiện tại của tổ chức.","k":"usurp"},{"t":"zealot","p":"noun","d":"Người cuồng tín","e":"The zealot could not tolerate any views that opposed his beliefs.","ev":"Người cuồng tín không thể chấp nhận bất kỳ quan điểm nào trái ngược với niềm tin của mình.","k":"zealot"},{"t":"assail","p":"verb","d":"Tấn công","e":"The critics began to assail the film for its lack of originality.","ev":"Các nhà phê bình bắt đầu chỉ trích bộ phim vì sự thiếu sáng tạo.","k":"assail"},{"t":"berate","p":"verb","d":"Mắng mỏ","e":"She berated him for being late to the important meeting.","ev":"Cô đã mắng mỏ anh vì đến muộn cuộc họp quan trọng.","k":"berate"},{"t":"castigate","p":"verb","d":"Trừng phạt","e":"The teacher castigated the students for their poor performance on the exam.","ev":"Giáo viên đã chỉ trích học sinh vì thành tích kém trong kỳ thi.","k":"castigate"},{"t":"censorious","p":"adj","d":"Chỉ trích","e":"His censorious attitude made it difficult for others to share their opinions.","ev":"Thái độ chỉ trích của anh khiến người khác khó chia sẻ ý kiến của mình.","k":"censorious"},{"t":"censure","p":"verb","d":"Khiển trách","e":"The senator faced censure for his inappropriate remarks.","ev":"Thượng nghị sĩ đã phải đối mặt với sự chỉ trích vì những nhận xét không thích hợp.","k":"censure"},{"t":"chastise","p":"verb","d":"Trừng phạt","e":"She chastised her son for not completing his homework.","ev":"Cô đã khiển trách con trai vì không hoàn thành bài tập về nhà.","k":"chastise"},{"t":"chide","p":"verb","d":"Mắng mỏ","e":"He chided his friend for being too careless with money.","ev":"Anh đã nhắc nhở bạn mình về việc quá bất cẩn với tiền bạc.","k":"chide"},{"t":"consternation","p":"noun","d":"Sự lo lắng","e":"The announcement of layoffs caused consternation among the employees.","ev":"Thông báo về việc cắt giảm nhân sự đã gây ra sự hoang mang trong số nhân viên.","k":"consternation"},{"t":"contempt(uous)","p":"adj","d":"Khinh miệt","e":"She looked at the critic with a contemptuous expression after the harsh review.","ev":"Cô nhìn người phê bình bằng vẻ mặt khinh bỉ sau bài đánh giá gay gắt.","k":"contempt(uous)"},{"t":"contemptible","p":"adj","d":"Đáng khinh","e":"His contemptible behavior during the meeting shocked everyone.","ev":"Hành vi đáng khinh của anh trong cuộc họp đã làm mọi người sốc.","k":"contemptible"},{"t":"culpable","p":"noun/adj","d":"Đáng trách","e":"The jury found the defendant culpable of the charges against him.","ev":"Bồi thẩm đoàn đã xác định bị cáo có tội đối với các cáo buộc chống lại anh.","k":"culpable"},{"t":"denigrate","p":"noun","d":"Gièm pha","e":"It's unfair to denigrate someone's work without understanding their effort.","ev":"Thật không công bằng khi hạ thấp công việc của ai đó mà không hiểu được nỗ lực của họ.","k":"denigrate"}]},{"n":"Buổi 16","c":[{"t":"deprecate","p":"verb","d":"Phê phán","e":"Many people deprecate the use of slang in formal writing.","ev":"Nhiều người không tán thành việc sử dụng tiếng lóng trong viết chính thức.","k":"deprecate"},{"t":"deride","p":"verb","d":"Châm biếm","e":"They derided his efforts to change the system as naïve.","ev":"Họ chế nhạo nỗ lực của anh để thay đổi hệ thống là ngây thơ.","k":"deride"},{"t":"derogatory, \nderogate","p":"adj","d":"Lăng mạ, hạ thấp","e":"The comments were derogatory and hurtful to the community.","ev":"Những bình luận đó đã xúc phạm và gây tổn thương cho cộng đồng.","k":"derogatory, derogate"},{"t":"discount (verb)","p":"verb","d":"Xem nhẹ","e":"Don’t discount his opinion just because he is young; he may have valuable insights.","ev":"Đừng xem nhẹ ý kiến của anh chỉ vì anh còn trẻ; anh có thể có những hiểu biết quý giá.","k":"discount (verb)"},{"t":"disparage","p":"verb","d":"Đánh giá thấp","e":"She disparaged his work, claiming it lacked originality.","ev":"Cô đã coi thường công việc của anh, cho rằng nó thiếu tính sáng tạo.","k":"disparage"},{"t":"eulogy, eulogize","p":"noun","d":"Điếu văn, khen ngợi","e":"At the funeral, a touching eulogy was delivered in honor of the deceased.","ev":"Tại đám tang, một bài điếu văn xúc động đã được đọc để tôn vinh người đã khuất.","k":"eulogy, eulogize"},{"t":"extol","p":"verb","d":"Tán dương","e":"The critics extolled the film for its stunning visuals and compelling story.","ev":"Các nhà phê bình ca ngợi bộ phim vì hình ảnh tuyệt đẹp và cốt truyện hấp dẫn.","k":"extol"},{"t":"laud, laudatory","p":"verb","d":"Khen ngợi, khen ngợi","e":"He received laudatory reviews for his performance in the play.","ev":"Anh đã nhận được những đánh giá khen ngợi cho màn trình diễn của mình trong vở kịch.","k":"laud, laudatory"},{"t":"noxious","p":"adj","d":"Độc hại","e":"The noxious fumes from the factory were harmful to the local environment.","ev":"Khí độc hại từ nhà máy gây ảnh hưởng xấu đến môi trường địa phương.","k":"noxious"},{"t":"reprehensible","p":"adj","d":"Đáng chỉ trích","e":"His reprehensible actions during the crisis drew widespread condemnation.","ev":"Hành động đáng lên án của anh trong cuộc khủng hoảng đã bị chỉ trích rộng rãi.","k":"reprehensible"},{"t":"reprimand","p":"verb","d":"Khiển trách","e":"The manager issued a reprimand to the employee for being late.","ev":"Quản lý đã đưa ra một hình phạt cho nhân viên vì đến muộn.","k":"reprimand"},{"t":"reproach","p":"verb","d":"Lời trách móc","e":"She looked at him with reproach when he failed to help.","ev":"Cô nhìn anh với ánh mắt trách móc khi anh không giúp đỡ.","k":"reproach"},{"t":"scathing","p":"adj","d":"Châm biếm","e":"The critic wrote a scathing review that damaged the restaurant's reputation.","ev":"Nhà phê bình đã viết một bài đánh giá cay độc làm hỏng danh tiếng của nhà hàng.","k":"scathing"},{"t":"slight (verb)","p":"verb","d":"Xem nhẹ","e":"He felt slighted when his contributions were ignored during the meeting.","ev":"Anh cảm thấy bị coi thường khi những đóng góp của mình bị phớt lờ trong cuộc họp.","k":"slight (verb)"},{"t":"spurn","p":"verb","d":"Khước từ","e":"She spurned his invitation to the party, preferring to stay home.","ev":"Cô đã từ chối lời mời của anh đến bữa tiệc, thích ở nhà hơn.","k":"spurn"},{"t":"tirade","p":"noun","d":"Diễn văn dài","e":"His tirade against the government lasted for over an hour.","ev":"Bài chỉ trích chính phủ của anh kéo dài hơn một giờ.","k":"tirade"},{"t":"tout","p":"verb","d":"Quảng cáo","e":"The company touted its new product as a revolutionary innovation.","ev":"Công ty đã quảng bá sản phẩm mới của mình như một đổi mới cách mạng.","k":"tout"},{"t":"affected","p":"adj","d":"Làm ra vẻ","e":"His affected mannerisms made him seem insincere to others.","ev":"Cách cư xử giả tạo của anh khiến anh có vẻ không chân thành trong mắt người khác.","k":"affected"},{"t":"chagrin","p":"noun","d":"Sự thất vọng","e":"To her chagrin, she realized she had forgotten her friend’s birthday.","ev":"Đến nỗi xấu hổ, cô nhận ra rằng mình đã quên sinh nhật của bạn.","k":"chagrin"},{"t":"complacency, \ncomplacent","p":"noun/adj","d":"Tự mãn, sự tự mãn","e":"His complacency about his performance led to a lack of improvement.","ev":"Sự tự mãn của anh về hiệu suất của mình đã dẫn đến việc thiếu cải thiện.","k":"complacency, complacent"}]},{"n":"Buổi 17","c":[{"t":"conciliate, \nconciliatory","p":"v/adj","d":"Xoa dịu, hòa giải","e":"The mediator tried to conciliate both parties during the negotiation.","ev":"Người hòa giải đã cố gắng hòa giải cả hai bên trong quá trình đàm phán.","k":"conciliate, conciliatory"},{"t":"degradation","p":"noun","d":"Sự suy thoái","e":"The degradation of the environment is a pressing issue for our generation.","ev":"Sự suy thoái của môi trường là một vấn đề cấp bách cho thế hệ của chúng ta.","k":"degradation"},{"t":"demure, demurral","p":"adj/noun","d":"Khiêm nhường, sự khiêm nhường","e":"She had a demure smile that belied her confident personality.","ev":"Cô có một nụ cười dịu dàng mà ẩn chứa tính cách tự tin của mình.","k":"demure, demurral"},{"t":"flippant, flippancy","p":"adj/noun","d":"Thô lỗ, sự thô lỗ","e":"His flippant remarks during the serious discussion annoyed everyone.","ev":"Những lời nói hời hợt của anh trong cuộc thảo luận nghiêm túc đã khiến mọi người khó chịu.","k":"flippant, flippancy"},{"t":"hubris","p":"noun","d":"Ngạo mạn","e":"His hubris ultimately led to his downfall.","ev":"Sự kiêu ngạo của anh cuối cùng đã dẫn đến sự sụp đổ của mình.","k":"hubris"},{"t":"ignominy, \nignominious","p":"adj/noun","d":"Sự nhục nhã, nhục nhã","e":"The ignominy of his actions was hard to bear in front of his peers.","ev":"Sự nhục nhã của hành động của anh thật khó chịu trước mặt các đồng nghiệp.","k":"ignominy, ignominious"},{"t":"imperious","p":"adj","d":"Hống hách","e":"The imperious tone in her voice made it clear she expected obedience.","ev":"Giọng điệu hống hách của cô khiến mọi người rõ ràng rằng cô mong muốn sự tuân thủ.","k":"imperious"},{"t":"impudence, \nimpudent","p":"noun/adj","d":"Xấc láo","e":"His impudence in addressing the teacher shocked the entire class.","ev":"Sự vô lễ của anh khi nói chuyện với giáo viên đã làm cả lớp sốc.","k":"impudence, impudent"},{"t":"insolence, insolent","p":"noun/adj","d":"Vô lễ, vô lễ","e":"The insolent behavior of the student earned him a detention.","ev":"Hành vi hỗn láo của học sinh đã khiến anh bị phạt ở lại lớp.","k":"insolence, insolent"},{"t":"irreverent, \nirreverence","p":"adj/noun","d":"Thiếu tôn trọng, sự thiếu tôn","e":"His irreverent jokes about serious topics offended many people.","ev":"Những câu đùa không tôn trọng của anh về các chủ đề nghiêm túc đã khiến nhiều người bị xúc phạm.","k":"irreverent, irreverence"},{"t":"notoriety, \nnotorious","p":"noun/adj","d":"Tai tiếng, tai tiếng","e":"The notoriety of the criminal made headlines across the country.","ev":"Sự nổi tiếng xấu của tội phạm đã khiến các tiêu đề trên toàn quốc.","k":"notoriety, notorious"},{"t":"obdurate","p":"adj","d":"Cứng đầu","e":"Despite her pleas, he remained obdurate and refused to change his mind.","ev":"Mặc dù cô đã cầu xin, anh vẫn cứng đầu và từ chối thay đổi quyết định của mình.","k":"obdurate"},{"t":"obstinate, -acy","p":"adj","d":"Cứng đầu, sự cứng đầu","e":"His obstinate refusal to listen caused a rift in their relationship.","ev":"Việc anh cứng đầu từ chối lắng nghe đã gây ra một cuộc rạn nứt trong mối quan hệ của họ.","k":"obstinate, -acy"},{"t":"opportunist, \nopportunistic","p":"adj/noun","d":"Tục lợi, tính tục lợi","e":"The opportunist took advantage of the situation to advance his own agenda.","ev":"Kẻ cơ hội đã lợi dụng tình huống để thúc đẩy chương trình của riêng mình.","k":"opportunist, opportunistic"},{"t":"peremptory","p":"adj","d":"Cứng rắn","e":"The boss's peremptory order left no room for discussion.","ev":"Lệnh hạ lệnh của sếp không để lại chỗ cho cuộc thảo luận.","k":"peremptory"},{"t":"presumptuous","p":"adj","d":"Xấc láo","e":"It was presumptuous of him to assume he would be invited to the wedding.","ev":"Thật kiêu ngạo khi anh giả định rằng mình sẽ được mời đến đám cưới.","k":"presumptuous"},{"t":"recalcitrant","p":"adj","d":"Cứng đầu","e":"The recalcitrant student refused to comply with the school rules.","ev":"Học sinh cứng đầu đã từ chối tuân thủ các quy định của trường.","k":"recalcitrant"},{"t":"self-righteous","p":"adj","d":"Tự mãn","e":"His self-righteous attitude alienated his friends.","ev":"Thái độ tự mãn của anh đã khiến bạn bè xa lánh.","k":"self-righteous"},{"t":"self-serving","p":"adj","d":"Vị kỷ","e":"Her self-serving motives were obvious to everyone in the room.","ev":"Động cơ vị kỷ của cô rõ ràng với mọi người trong phòng.","k":"self-serving"},{"t":"supercilious","p":"adj","d":"Kiêu ngạo","e":"The supercilious remarks from the guest made everyone uncomfortable.","ev":"Những lời nhận xét kiêu ngạo của vị khách đã khiến mọi người cảm thấy khó chịu.","k":"supercilious"}]},{"n":"Buổi 18","c":[{"t":"unabashed","p":"adj","d":"Không xấu hổ","e":"She was unabashed about her opinions, expressing them freely at the meeting.","ev":"Cô không hề xấu hổ về ý kiến của mình, tự do bày tỏ chúng trong cuộc họp.","k":"unabashed"},{"t":"wayward","p":"adj","d":"Bướng bỉnh","e":"The wayward child often disobeyed his parents’ rules.","ev":"Đứa trẻ bướng bỉnh thường không tuân theo các quy tắc của cha mẹ.","k":"wayward"},{"t":"bog","p":"noun","d":"Đầm lầy","e":"The heavy rains caused the fields to bog down, making it difficult to plant crops.","ev":"Những trận mưa lớn khiến các cánh đồng lầy lội, làm khó khăn cho việc trồng trọt.","k":"bog"},{"t":"coalesce","p":"noun/verb","d":"Kết hợp","e":"The two rivers coalesce into one larger river at the valley.","ev":"Hai con sông hợp nhất thành một con sông lớn hơn tại thung lũng.","k":"coalesce"},{"t":"confluence","p":"noun","d":"Sự hợp lưu","e":"The confluence of different cultures enriched the community.","ev":"Sự giao thoa của các nền văn hóa khác nhau đã làm phong phú cộng đồng.","k":"confluence"},{"t":"disseminate","p":"verb","d":"Phân phát","e":"The organization aims to disseminate information about health and wellness.","ev":"Tổ chức này nhằm mục đích truyền bá thông tin về sức khỏe và sự lành mạnh.","k":"disseminate"},{"t":"effervesce","p":"noun","d":"Sủi bọt","e":"The soda began to effervesce as soon as the cap was removed.","ev":"Nước ngọt bắt đầu sủi bọt ngay khi nắp được mở.","k":"effervesce"},{"t":"elicit","p":"verb","d":"Kích thích","e":"The teacher aimed to elicit responses from all the students during the discussion.","ev":"Giáo viên nhằm mục đích thu hút phản hồi từ tất cả học sinh trong cuộc thảo luận.","k":"elicit"},{"t":"indigenous","p":"adj","d":"Bản địa","e":"The indigenous people of the region have a rich cultural heritage.","ev":"Người bản địa của khu vực này có một di sản văn hóa phong phú.","k":"indigenous"},{"t":"induce","p":"verb","d":"Gây ra","e":"The medication may induce drowsiness, so be cautious when driving.","ev":"Thuốc có thể gây buồn ngủ, vì vậy hãy cẩn thận khi lái xe.","k":"induce"},{"t":"inert, inertia","p":"adj/noun","d":"Bất động, sự bất động","e":"The inert materials in the reaction did not contribute to the outcome.","ev":"Các vật liệu bất động trong phản ứng không góp phần vào kết quả.","k":"inert, inertia"},{"t":"inherent","p":"adj","d":"Vốn có","e":"The concept of freedom is inherent in the country's constitution.","ev":"Khái niệm về tự do là vốn có trong hiến pháp của quốc gia.","k":"inherent"},{"t":"multifarious","p":"adj","d":"Đa dạng","e":"The market offers a multifarious selection of goods and services.","ev":"Thị trường cung cấp một loạt các hàng hóa và dịch vụ đa dạng.","k":"multifarious"},{"t":"precipitate","p":"verb","d":"Xảy ra đột ngột","e":"Heavy rains can precipitate landslides in hilly areas.","ev":"Mưa lớn có thể gây ra lở đất ở các khu vực đồi núi.","k":"precipitate"},{"t":"abate","p":"verb","d":"Giảm bớt","e":"The storm will abate by morning, making travel easier.","ev":"Cơn bão sẽ giảm bớt vào buổi sáng, giúp việc di chuyển dễ dàng hơn.","k":"abate"},{"t":"allocate","p":"verb","d":"Phân phối","e":"The committee will allocate funds to support local charities.","ev":"Ủy ban sẽ phân bổ quỹ để hỗ trợ các tổ chức từ thiện địa phương.","k":"allocate"},{"t":"atrophy","p":"verb","d":"Tiêu hao","e":"If not used, muscles can atrophy over time.","ev":"Nếu không sử dụng, cơ bắp có thể teo lại theo thời gian.","k":"atrophy"},{"t":"attenuate","p":"verb","d":"Làm yếu đi","e":"The new law will attenuate the effects of pollution in the city.","ev":"Luật mới sẽ làm giảm tác động của ô nhiễm trong thành phố.","k":"attenuate"},{"t":"burgeon","p":"verb","d":"Phát triển nhanh","e":"The plant began to burgeon once the spring rains arrived.","ev":"Cây bắt đầu nảy nở khi những cơn mưa mùa xuân đến.","k":"burgeon"},{"t":"circumscribe","p":"verb","d":"Hạn chế","e":"The regulations circumscribe the activities of the organization to ensure compliance.","ev":"Các quy định giới hạn hoạt động của tổ chức để đảm bảo tuân thủ.","k":"circumscribe"}]},{"n":"Buổi 19","c":[{"t":"copious","p":"adj","d":"Dồi dào","e":"The researcher took copious notes during the lecture to ensure she didn't miss any details.","ev":"Nhà nghiên cứu đã ghi chép rất nhiều trong suốt bài giảng để đảm bảo không bỏ lỡ chi tiết nào.","k":"copious"},{"t":"dearth","p":"noun","d":"Thiếu thốn","e":"There was a dearth of resources available for the project, hindering its progress.","ev":"Có sự thiếu hụt tài nguyên cho dự án, cản trở tiến trình của nó.","k":"dearth"},{"t":"devoid","p":"adj","d":"Thiếu","e":"The area was devoid of wildlife due to extensive urban development.","ev":"Khu vực này hoàn toàn thiếu động vật hoang dã do sự phát triển đô thị rộng rãi.","k":"devoid"},{"t":"diffuse","p":"adj","d":"Khuếch tán","e":"The light from the lamp began to diffuse throughout the room.","ev":"Ánh sáng từ đèn bắt đầu lan tỏa khắp phòng.","k":"diffuse"},{"t":"diminutive, \ndiminution","p":"adj/noun","d":"Nhỏ bé, sự giảm đi","e":"The diminutive size of the puppy made it incredibly cute.","ev":"Kích thước nhỏ bé của chú chó con khiến nó trở nên rất dễ thương.","k":"diminutive, diminution"},{"t":"efface(ment)","p":"noun","d":"Xóa bỏ","e":"The artist's work showed a gradual effacement of earlier styles as she developed her own.","ev":"Công việc của nghệ sĩ cho thấy sự xóa nhòa dần dần các phong cách trước đó khi cô phát triển phong cách riêng.","k":"efface(ment)"},{"t":"encompass","p":"verb","d":"Bao gồm","e":"The project aims to encompass a wide range of topics relevant to climate change.","ev":"Dự án nhằm bao quát nhiều chủ đề liên quan đến biến đổi khí hậu.","k":"encompass"},{"t":"encroaching","p":"verb","d":"Xâm lấn","e":"The encroaching fog made it difficult to see the road ahead.","ev":"Sương mù đang đến gần khiến việc nhìn đường phía trước trở nên khó khăn.","k":"encroaching"},{"t":"excavate","p":"verb","d":"Khai thác","e":"Archaeologists will excavate the site to uncover ancient artifacts.","ev":"Các nhà khảo cổ học sẽ khai thác địa điểm để tìm ra các hiện vật cổ xưa.","k":"excavate"},{"t":"extricate","p":"verb","d":"Giải thoát","e":"She managed to extricate herself from the difficult situation with grace.","ev":"Cô đã thành công trong việc thoát khỏi tình huống khó khăn một cách duyên dáng.","k":"extricate"},{"t":"gargantuan","p":"verb","d":"Khổng lồ","e":"The gargantuan statue drew visitors from all over the world.","ev":"Bức tượng khổng lồ thu hút du khách từ khắp nơi trên thế giới.","k":"gargantuan"},{"t":"germinate","p":"verb","d":"nảy mầm","e":"The seeds will germinate when the conditions are right.","ev":"Hạt sẽ nảy mầm khi các điều kiện thuận lợi.","k":"germinate"},{"t":"hamper (verb)","p":"verb","d":"Ở ấp","e":"Heavy rains can hamper the construction process significantly.","ev":"Mưa lớn có thể cản trở quá trình xây dựng một cách đáng kể.","k":"hamper (verb)"},{"t":"incubate","p":"verb","d":"Bừa bãi","e":"The eggs will incubate for about three weeks before hatching.","ev":"Những quả trứng sẽ được ấp trong khoảng ba tuần trước khi nở.","k":"incubate"},{"t":"indiscriminate","p":"adj","d":"Ngăn chặn","e":"His indiscriminate use of resources led to waste and inefficiency.","ev":"Việc anh sử dụng tài nguyên một cách bừa bãi đã dẫn đến lãng phí và thiếu hiệu quả.","k":"indiscriminate"},{"t":"inhibit(ing)","p":"verb","d":"Bẩm sinh","e":"The drug can inhibit the growth of harmful bacteria.","ev":"Thuốc có thể ức chế sự phát triển của vi khuẩn có hại.","k":"inhibit(ing)"},{"t":"innate","p":"adj","d":"Không độc hại","e":"She had an innate ability to understand complex problems quickly.","ev":"Cô có khả năng bẩm sinh để hiểu các vấn đề phức tạp một cách nhanh chóng.","k":"innate"},{"t":"innocuous","p":"adj","d":"Tính chất biệt lập","e":"The innocuous remark was taken out of context and caused unnecessary drama.","ev":"Nhận xét vô hại đã bị hiểu sai trong ngữ cảnh và gây ra những rắc rối không cần thiết.","k":"innocuous"},{"t":"insular(ity)","p":"adj/noun","d":"Ngập tràn","e":"His insularity prevented him from understanding the broader implications of the issue.","ev":"Sự tách biệt của anh đã ngăn cản anh hiểu các tác động rộng lớn hơn của vấn đề.","k":"insular(ity)"}]},{"n":"Buổi 20","c":[{"t":"inundate","p":"verb","d":"Tiềm ẩn, sự tiềm ẩn","e":"The heavy rains will inundate the fields, causing flooding in the area.","ev":"Những cơn mưa lớn sẽ làm ngập các cánh đồng, gây ra lũ lụt trong khu vực.","k":"inundate"},{"t":"latent, latency","p":"adj","d":"Giảm nhẹ","e":"The scientist studied the latent effects of the drug over several months.","ev":"Nhà khoa học đã nghiên cứu tác động tiềm ẩn của thuốc trong vài tháng.","k":"latent, latency"},{"t":"mitigate, mitigator","p":"verb/noun","d":"Một ít","e":"We need to find ways to mitigate the risks associated with the project.","ev":"Chúng ta cần tìm cách giảm thiểu những rủi ro liên quan đến dự án.","k":"mitigate, mitigator"},{"t":"modicum","p":"noun","d":"Đa dạng","e":"She only had a modicum of experience, but she was eager to learn more.","ev":"Cô chỉ có một chút kinh nghiệm, nhưng cô rất háo hức để học hỏi thêm.","k":"modicum"},{"t":"motley","p":"noun","d":"Nung nóng","e":"The motley crowd at the festival included people of all ages and backgrounds.","ev":"Đám đông đa dạng tại lễ hội bao gồm người thuộc đủ mọi lứa tuổi và nền tảng khác nhau.","k":"motley"},{"t":"parch","p":"adj","d":"Sự thiếu thốn","e":"The sun can parch the earth, making it difficult for plants to survive.","ev":"Mặt trời có thể làm khô cằn đất, khiến cây cối khó sống sót.","k":"parch"},{"t":"paucity","p":"noun","d":"Ngoại vi","e":"The paucity of information made it challenging to draw any conclusions.","ev":"Sự thiếu hụt thông tin đã khiến việc rút ra bất kỳ kết luận nào trở nên khó khăn.","k":"paucity"},{"t":"peripheral","p":"noun","d":"Tính dẻo","e":"The peripheral devices were not functioning correctly with the computer.","ev":"Các thiết bị ngoại vi đã không hoạt động chính xác với máy tính.","k":"peripheral"},{"t":"plasticity","p":"adj","d":"Sự dư thừa","e":"The plasticity of the brain allows it to adapt to new experiences throughout life.","ev":"Độ dẻo dai của não cho phép nó thích nghi với những trải nghiệm mới trong suốt cuộc đời.","k":"plasticity"},{"t":"plethora, plethoric","p":"noun","d":"Dễ uốn nắn","e":"There was a plethora of options available for consumers in the market.","ev":"Có rất nhiều sự lựa chọn cho người tiêu dùng trên thị trường.","k":"plethora, plethoric"},{"t":"pliable, pliant","p":"adj","d":"Ngăn chặn","e":"The material is pliable and can be easily shaped into different forms.","ev":"Chất liệu này dẻo và có thể dễ dàng tạo hình thành các dạng khác nhau.","k":"pliable, pliant"},{"t":"preclude","p":"verb","d":"Khổng lồ","e":"His lack of experience does not preclude him from applying for the job.","ev":"Thiếu kinh nghiệm của anh không ngăn cản anh nộp đơn xin việc.","k":"preclude"},{"t":"prodigious","p":"verb","d":"Dồi dào, sự dồi dào","e":"The prodigious talent of the young musician amazed everyone at the concert.","ev":"Tài năng phi thường của nhạc sĩ trẻ đã khiến mọi người kinh ngạc tại buổi hòa nhạc.","k":"prodigious"},{"t":"profuse, profusion","p":"noun","d":"Cấm đoán, sự cấm đoán","e":"She offered profuse apologies for her mistake.","ev":"Cô đã gửi lời xin lỗi dồn dập về sai lầm của mình.","k":"profuse, profusion"},{"t":"prohibitive, \nprohibition","p":"adj/noun","d":"Tăng nhanh, sự tăng nhanh","e":"The prohibitive costs of living in the city discourage many from moving there.","ev":"Chi phí sinh hoạt cắt cổ ở thành phố khiến nhiều người không muốn chuyển đến đó.","k":"prohibitive, prohibition"},{"t":"proliferate, \nproliferation","p":"noun","d":"Sản xuất nhiều","e":"The use of social media has proliferated in recent years, changing how we communicate.","ev":"Việc sử dụng mạng xã hội đã gia tăng nhanh chóng trong những năm gần đây, thay đổi cách chúng ta giao tiếp.","k":"proliferate, proliferation"},{"t":"prolific","p":"adj","d":"Dẹp yên","e":"He is a prolific writer, publishing several books each year.","ev":"Anh là một nhà văn phong phú, xuất bản nhiều cuốn sách mỗi năm.","k":"prolific"},{"t":"quell","p":"verb","d":"Hoành hành","e":"The police were called to quell the disturbance at the event.","ev":"Cảnh sát đã được gọi đến để dập tắt sự náo động tại sự kiện.","k":"quell"},{"t":"rampant","p":"adj","d":"Thèm thuồng","e":"The rampant spread of misinformation is a serious issue in today's society.","ev":"Sự lan truyền tràn lan của thông tin sai lệch là một vấn đề nghiêm trọng trong xã hội ngày nay.","k":"rampant"},{"t":"ravenous","p":"noun","d":"Gặt hái","e":"After skipping breakfast, he felt ravenous by lunchtime.","ev":"Sau khi bỏ bữa sáng, anh cảm thấy đói cồn cào vào giờ ăn trưa.","k":"ravenous"}]},{"n":"Buổi 21","c":[{"t":"reap","p":"verb","d":"Rút lui","e":"If you work hard, you will reap the rewards of your efforts.","ev":"Nếu bạn làm việc chăm chỉ, bạn sẽ gặt hái được thành quả từ nỗ lực của mình.","k":"reap"},{"t":"recessive","p":"adj","d":"Giảm cấp","e":"Blue eyes are a recessive trait, meaning they can be masked by dominant traits.","ev":"Mắt xanh là một đặc điểm lặn, có nghĩa là nó có thể bị che khuất bởi các đặc điểm trội.","k":"recessive"},{"t":"relegate","p":"verb","d":"Từ bỏ","e":"She was relegated to a lesser role after the merger.","ev":"Cô đã bị hạ xuống một vai trò thấp hơn sau khi sáp nhập.","k":"relegate"},{"t":"relinquish","p":"verb","d":"Kho tàng","e":"He decided to relinquish his claim to the inheritance.","ev":"Anh quyết định từ bỏ quyền thừa kế của mình.","k":"relinquish"},{"t":"repertory","p":"noun","d":"Thoả mãn","e":"The repertory theater produces a variety of plays throughout the year.","ev":"Nhà hát lưu trữ sản xuất nhiều vở kịch khác nhau trong suốt cả năm.","k":"repertory"},{"t":"satiate","p":"verb","d":"Bão hòa","e":"The dessert was rich enough to satiate even the sweetest tooth.","ev":"Món tráng miệng đủ phong phú để làm thỏa mãn cả những người thích ngọt nhất.","k":"satiate"},{"t":"saturate","p":"verb","d":"Thiếu thốn","e":"The sponge will saturate with water if left in it for too long.","ev":"Bọt biển sẽ bão hòa với nước nếu để trong đó quá lâu.","k":"saturate"},{"t":"scanty","p":"adj","d":"Phạm vi","e":"The scanty clothing was not suitable for the cold weather.","ev":"Quần áo mỏng manh không phù hợp cho thời tiết lạnh.","k":"scanty"},{"t":"scope","p":"noun","d":"Thừa thãi","e":"The scope of the project includes both research and implementation phases.","ev":"Phạm vi của dự án bao gồm cả giai đoạn nghiên cứu và thực hiện.","k":"scope"},{"t":"superfluous","p":"adj","d":"Sự thừa thãi","e":"The report was full of superfluous information that was not necessary.","ev":"Báo cáo đầy rẫy thông tin thừa thãi mà không cần thiết.","k":"superfluous"},{"t":"surfeit","p":"noun","d":"Đầy ắp","e":"After the feast, they were left with a surfeit of food.","ev":"Sau bữa tiệc, họ bị bỏ lại với một lượng thức ăn thừa thãi.","k":"surfeit"},{"t":"teem, teeming","p":"verb","d":"Không đáng kể","e":"The lake was teeming with fish during the summer months.","ev":"Hồ đầy cá vào những tháng mùa hè.","k":"teem, teeming"},{"t":"trifling","p":"adj","d":"Khắp nơi","e":"He dismissed the issue as trifling and not worth his time.","ev":"Anh coi thường vấn đề là không đáng kể và không xứng đáng với thời gian của mình.","k":"trifling"},{"t":"ubiquitous","p":"adj","d":"Trống rỗng","e":"Smartphones have become ubiquitous in modern society.","ev":"Điện thoại thông minh đã trở nên phổ biến trong xã hội hiện đại.","k":"ubiquitous"},{"t":"vacuous, vacuity","p":"adj/noun","d":"Dính","e":"The vacuous expression on his face showed he was not paying attention.","ev":"Biểu cảm trống rỗng trên khuôn mặt anh cho thấy anh không chú ý.","k":"vacuous, vacuity"},{"t":"viscous","p":"adj","d":"Suy giảm","e":"The syrup was thick and viscous, making it difficult to pour.","ev":"Syrup đặc và sánh, khiến việc rót trở nên khó khăn.","k":"viscous"},{"t":"waning","p":"adj","d":"Phức tạp","e":"Her enthusiasm for the project was waning as the deadline approached.","ev":"Sự hào hứng của cô với dự án đang giảm dần khi thời hạn đến gần.","k":"waning"},{"t":"byzantine","p":"adj","d":"Chói tai, âm thanh chói tai","e":"The byzantine structure of the organization made it hard to navigate.","ev":"Cấu trúc phức tạp của tổ chức khiến việc điều hướng trở nên khó khăn.","k":"byzantine"},{"t":"cacophonous, \ncacophony","p":"adj/noun","d":"Lướt qua","e":"The cacophonous sounds of the city can be overwhelming at times.","ev":"Âm thanh hỗn tạp của thành phố đôi khi có thể khiến ta choáng ngợp.","k":"cacophonous, cacophony"},{"t":"cursory","p":"adj","d":"Cách đi","e":"He gave the report a cursory glance before submitting it.","ev":"Anh chỉ liếc qua báo cáo một cách hời hợt trước khi nộp.","k":"cursory"}]},{"n":"Buổi 22","c":[{"t":"gait","p":"noun","d":"Lòe loẹt","e":"She walked with a graceful gait.","ev":"Cô ấy đi với dáng đi uyển chuyển.","k":"gait"},{"t":"garish","p":"adj","d":"Tham ăn","e":"The room was decorated in garish colors.","ev":"Căn phòng được trang trí bằng màu sắc lòe loẹt.","k":"garish"},{"t":"glutton(ous)","p":"noun/adj","d":"Kinh khủng","e":"He was a glutton for punishment.","ev":"Anh ta là người tham ăn; thích chịu đựng khổ sở.","k":"glutton(ous)"},{"t":"lurid","p":"adj","d":"Dễ uốn nắn","e":"The movie was filled with lurid details.","ev":"Bộ phim đầy những chi tiết gây sốc.","k":"lurid"},{"t":"malleable","p":"adj","d":"Đổ nát","e":"Gold is a malleable metal.","ev":"Vàng là kim loại dễ uốn.","k":"malleable"},{"t":"ramshackle","p":"adj","d":"Tỏa ra mùi","e":"The ramshackle house was falling apart.","ev":"Ngôi nhà tồi tàn đang bị sụp đổ.","k":"ramshackle"},{"t":"redolent","p":"adj","d":"Che phủ","e":"The garden was redolent of roses.","ev":"Khu vườn có mùi thơm của hoa hồng.","k":"redolent"},{"t":"shroud","p":"adj","d":"Hoàn toàn","e":"The fog acted like a shroud over the city.","ev":"Sương mù bao phủ thành phố như một lớp khăn.","k":"shroud"},{"t":"stark(ness)","p":"noun","d":"Ngon lành","e":"The starkness of the landscape was breathtaking.","ev":"Sự trần trụi của phong cảnh thật đẹp mắt.","k":"stark(ness)"},{"t":"succulent","p":"adj","d":"Cổ xưa","e":"The steak was juicy and succulent.","ev":"Miếng bít tết thật ngon và mọng nước.","k":"succulent"},{"t":"antediluvian","p":"adj","d":"Chậm trễ","e":"His ideas were antediluvian and outdated.","ev":"Ý tưởng của anh ta cổ xưa và lạc hậu.","k":"antediluvian"},{"t":"dilatory","p":"adj","d":"Ngắn ngủi","e":"His dilatory tactics annoyed the manager.","ev":"Chiến thuật chậm chạp của anh ta làm phiền quản lý.","k":"dilatory"},{"t":"ephemeral","p":"adj","d":"Thúc đẩy","e":"The beauty of the sunset was ephemeral.","ev":"Vẻ đẹp của hoàng hôn thật ngắn ngủi.","k":"ephemeral"},{"t":"hasten","p":"verb","d":"Tiên tri","e":"Please hasten your response.","ev":"Xin vui lòng trả lời nhanh chóng.","k":"hasten"},{"t":"oracle","p":"noun","d":"Dự kiến","e":"The oracle foretold the future.","ev":"Người tiên tri đã dự đoán tương lai.","k":"oracle"},{"t":"prospective","p":"noun","d":"Thoái hóa","e":"They are prospective clients.","ev":"Họ là những khách hàng tiềm năng.","k":"prospective"},{"t":"regressive","p":"adj","d":"Thỉnh thoảng","e":"The policy was seen as regressive.","ev":"Chính sách đó được coi là lùi lại.","k":"regressive"},{"t":"sporadic","p":"adj","d":"Đứng yên","e":"The rain was sporadic throughout the day.","ev":"Cơn mưa xảy ra rải rác suốt cả ngày.","k":"sporadic"},{"t":"temporize","p":"verb","d":"Quy định","e":"They decided to temporize until a decision was made.","ev":"Họ quyết định trì hoãn cho đến khi có quyết định.","k":"temporize"},{"t":"transient","p":"adj","d":"Nhút nhát","e":"The transient nature of life can be beautiful.","ev":"Bản chất tạm thời của cuộc sống có thể rất đẹp.","k":"transient"}]},{"n":"Buổi 23","c":[{"t":"arcane","p":"adj","d":"Tạm thời","e":"The instructions were filled with arcane language.","ev":"Hướng dẫn chứa đầy ngôn ngữ bí ẩn.","k":"arcane"},{"t":"belie","p":"verb","d":"Không ngừng nghỉ","e":"His calm demeanor belies the chaos within.","ev":"Vẻ điềm tĩnh của anh ta che giấu sự hỗn loạn bên trong.","k":"belie"},{"t":"charlatan","p":"noun","d":"Cảnh giác","e":"The charlatan promised miraculous results.","ev":"Kẻ lừa đảo hứa hẹn kết quả kỳ diệu.","k":"charlatan"},{"t":"circuitous","p":"adj","d":"Tùy ý","e":"Their route was circuitous, taking much longer.","ev":"Tuyến đường của họ quanh co, mất nhiều thời gian hơn.","k":"circuitous"},{"t":"clandestine","p":"adj","d":"Thúc đẩy","e":"They held a clandestine meeting in the woods.","ev":"Họ tổ chức một cuộc họp bí mật trong rừng.","k":"clandestine"},{"t":"demystify","p":"verb","d":"Xóa bỏ","e":"The goal was to demystify complex theories.","ev":"Mục tiêu là làm rõ những lý thuyết phức tạp.","k":"demystify"},{"t":"disingenuous","p":"adj","d":"Lén lút","e":"Her disingenuous smile made me suspicious.","ev":"Nụ cười không chân thật của cô ấy khiến tôi nghi ngờ.","k":"disingenuous"},{"t":"divulge","p":"verb","d":"Không thay đổi","e":"He refused to divulge any details.","ev":"Anh ta từ chối tiết lộ bất kỳ chi tiết nào.","k":"divulge"},{"t":"dupe","p":"verb","d":"Không thỏa hiệp","e":"Don't let him dupe you with his charm.","ev":"Đừng để anh ta lừa gạt bạn bằng sự quyến rũ của mình.","k":"dupe"},{"t":"duplicitous, \nduplicity","p":"adj/noun","d":"Uể oải","e":"His duplicitous nature led to many betrayals.","ev":"Bản chất lừa dối của anh ta đã dẫn đến nhiều vụ phản bội.","k":"duplicitous, duplicity"},{"t":"enigma(tic)","p":"noun","d":"Mẫu mực","e":"The enigma of her disappearance puzzled everyone.","ev":"Bí ẩn về sự biến mất của cô ấy làm mọi người bối rối.","k":"enigma(tic)"},{"t":"exposé","p":"noun","d":"Vĩnh cửu","e":"The exposé revealed the truth behind the scandal.","ev":"Bài báo điều tra tiết lộ sự thật về vụ bê bối.","k":"exposé"},{"t":"fallacious","p":"adj","d":"Tái phạm","e":"His argument was based on fallacious reasoning.","ev":"Lập luận của anh ta dựa trên lý lẽ sai lầm.","k":"fallacious"},{"t":"fallacy","p":"noun","d":"Lẫn nhau","e":"The fallacy of that statement is clear.","ev":"Sự sai lầm trong phát biểu đó là rõ ràng.","k":"fallacy"},{"t":"fraudulent","p":"adj","d":"Đạo đức giả","e":"The fraudulent scheme was uncovered by authorities.","ev":"Kế hoạch gian lận đã bị các cơ quan phát hiện.","k":"fraudulent"},{"t":"furtive","p":"adj","d":"Cách ly","e":"She cast a furtive glance at the document.","ev":"Cô ấy liếc nhìn một cách vụng trộm vào tài liệu.","k":"furtive"},{"t":"incredulous, \nincredulity","p":"noun","d":"Lén lút","e":"He was incredulous when he heard the news.","ev":"Anh ta không thể tin khi nghe tin tức.","k":"incredulous, incredulity"},{"t":"indeterminate","p":"adj","d":"Ngắn ngủi","e":"The outcome was indeterminate until the last minute.","ev":"Kết quả không xác định cho đến phút cuối.","k":"indeterminate"},{"t":"inscrutable","p":"adj","d":"Đa dạng","e":"His inscrutable expression made it hard to read him.","ev":"Biểu cảm bí ẩn của anh ta khiến việc đọc vị khó khăn.","k":"inscrutable"},{"t":"irony, ironic","p":"noun","d":"Mãnh liệt","e":"The irony of the situation was not lost on anyone.","ev":"Sự mỉa mai của tình huống không bị bỏ qua với bất kỳ ai.","k":"irony, ironic"}]},{"n":"Buổi 24","c":[{"t":"ostensible","p":"adj","d":"Ách","e":"His ostensible reason for leaving was unconvincing.","ev":"Lý do bề ngoài của anh ta khi rời đi không thuyết phục.","k":"ostensible"},{"t":"plausible, \nplausibility","p":"adj","d":"Hứng thú","e":"The explanation seemed plausible at first glance.","ev":"Giải thích có vẻ hợp lý ngay từ cái nhìn đầu tiên.","k":"plausible, plausibility"},{"t":"pretext","p":"noun","d":"lý do giả tạo","e":"He used a pretext to avoid the meeting.","ev":"Anh ta đã dùng lý do giả để tránh cuộc họp.","k":"pretext"},{"t":"prevaricator","p":"noun","d":"người nói dối","e":"A prevaricator can never be trusted.","ev":"Kẻ quanh co không bao giờ có thể được tin cậy.","k":"prevaricator"},{"t":"rectify, rectitude","p":"noun","d":"chính trực","e":"They tried to rectify the situation.","ev":"Họ đã cố gắng chỉnh sửa tình huống.","k":"rectify, rectitude"},{"t":"refutation, refute","p":"noun","d":"bác bỏ, phản bác","e":"The refutation of his argument was thorough.","ev":"Sự bác bỏ lập luận của anh ta rất thấu đáo.","k":"refutation, refute"},{"t":"sanctimonious","p":"adj","d":"đạo đức giả, tỏ ra thánh thiện","e":"She made a sanctimonious speech about ethics.","ev":"Cô ấy đã có một bài phát biểu đạo đức giả về đạo đức.","k":"sanctimonious"},{"t":"sophistry","p":"noun","d":"ngụy biện, lý do giả dối","e":"His argument was nothing more than sophistry.","ev":"Lập luận của anh ta chẳng qua chỉ là lý lẽ ranh mãnh.","k":"sophistry"},{"t":"spurious","p":"adj","d":"giả mạo, không chính xác","e":"The claims turned out to be spurious.","ev":"Các tuyên bố hóa ra là giả mạo.","k":"spurious"},{"t":"substantiate","p":"verb","d":"chứng minh, làm rõ","e":"They need evidence to substantiate their claims.","ev":"Họ cần bằng chứng để chứng minh các tuyên bố của mình.","k":"substantiate"},{"t":"auspicious","p":"adj","d":"may mắn, thuận lợi","e":"The signs were auspicious for a successful outcome.","ev":"Các dấu hiệu rất thuận lợi cho một kết quả thành công.","k":"auspicious"},{"t":"barrage","p":"noun","d":"sự tấn công dồn dập","e":"The barrage of questions overwhelmed her.","ev":"Cơn mưa câu hỏi đã làm cô ấy choáng ngợp.","k":"barrage"},{"t":"belligerent","p":"adj","d":"hiếu chiến, gây hấn","e":"His belligerent attitude caused many conflicts.","ev":"Thái độ hiếu chiến của anh ta đã gây ra nhiều xung đột.","k":"belligerent"},{"t":"blighted","p":"adj","d":"phá hủy","e":"The crops were blighted by the drought.","ev":"Cây trồng đã bị thiệt hại do hạn hán.","k":"blighted"},{"t":"bolster","p":"verb","d":"ủng hộ","e":"They implemented changes to bolster their defenses.","ev":"Họ đã thực hiện các thay đổi để củng cố phòng thủ.","k":"bolster"},{"t":"buttress","p":"verb","d":"ủng hộ, củng cố (thường dùng trong kiến thức","e":"The new law will buttress existing regulations.","ev":"Luật mới sẽ củng cố các quy định hiện có.","k":"buttress"},{"t":"circumvent","p":"verb","d":"vượt qua","e":"She tried to circumvent the rules.","ev":"Cô ấy cố gắng lách luật.","k":"circumvent"},{"t":"conflagration","p":"noun","d":"đại hỏa hoạn, vụ cháy lớn","e":"The conflagration destroyed several homes.","ev":"Ngọn lửa lớn đã phá hủy nhiều ngôi nhà.","k":"conflagration"},{"t":"contentious","p":"noun","d":"gây tranh cãi, hay tranh luận","e":"The contentious issue sparked a heated debate.","ev":"Vấn đề gây tranh cãi đã kích thích một cuộc tranh luận sôi nổi.","k":"contentious"},{"t":"decimate","p":"verb","d":"tàn phá","e":"The disease could decimate the population.","ev":"Bệnh dịch có thể tiêu diệt dân số.","k":"decimate"}]},{"n":"Buổi 25","c":[{"t":"deleterious","p":"adj","d":"gây hại","e":"The chemical had deleterious effects on the environment.","ev":"Chất hóa học có tác động có hại đến môi trường.","k":"deleterious"},{"t":"depravity","p":"noun","d":"đồi bại, sa đọa về mặt đạo đức","e":"His depravity shocked everyone at the party.","ev":"Sự suy đồi của anh ta đã khiến mọi người sốc tại bữa tiệc.","k":"depravity"},{"t":"dire","p":"adj","d":"nghiêm trọng, đáng lo ngại","e":"The situation is dire and requires immediate action.","ev":"Tình huống rất nghiêm trọng và cần hành động ngay lập tức.","k":"dire"},{"t":"divergent","p":"adj","d":"khác biệt","e":"Their divergent opinions led to a heated discussion.","ev":"Ý kiến khác nhau của họ đã dẫn đến một cuộc thảo luận sôi nổi.","k":"divergent"},{"t":"divisive","p":"adj","d":"gây chia rẽ, gây thù","e":"The proposal was seen as divisive among the team.","ev":"Đề xuất bị coi là gây chia rẽ trong nhóm.","k":"divisive"},{"t":"elude","p":"verb","d":"lẩn tránh","e":"The thief managed to elude capture.","ev":"Kẻ trộm đã quản lý để thoát khỏi bị bắt.","k":"elude"},{"t":"elusive","p":"adj","d":"khó nắm bắt, mơ hồ","e":"Her thoughts were elusive, hard to pin down.","ev":"Những suy nghĩ của cô ấy rất khó nắm bắt.","k":"elusive"},{"t":"embitter(ed)","p":"adj","d":"làm sự việc trở lên tồi tệ hơn","e":"Years of resentment had embittered him.","ev":"Nhiều năm oán hận đã làm cho anh ta cay đắng.","k":"embitter(ed)"},{"t":"encumbrance","p":"noun","d":"cản trở, gánh nặng","e":"He considered his debts an encumbrance.","ev":"Anh ta coi nợ nần của mình là một gánh nặng.","k":"encumbrance"},{"t":"fortuitous","p":"adj","d":"may mắn, tình cờ, ngẫu nhiên","e":"It was a fortuitous meeting that changed everything.","ev":"Đó là một cuộc gặp gỡ tình cờ đã thay đổi mọi thứ.","k":"fortuitous"},{"t":"marred","p":"adj","d":"làm hỏng, tổn thương","e":"The painting was marred by water damage.","ev":"Bức tranh bị hư hại bởi nước.","k":"marred"},{"t":"nefarious","p":"adj","d":"đê tiện, xấu xa","e":"The villain's nefarious plans were finally revealed.","ev":"Kế hoạch tội ác của kẻ phản diện cuối cùng đã bị lộ.","k":"nefarious"},{"t":"palliate, palliative","p":"noun","d":"làm giảm nhẹ, đỡ đau","e":"They tried to palliate the pain with medication.","ev":"Họ đã cố gắng giảm nhẹ cơn đau bằng thuốc.","k":"palliate, palliative"},{"t":"precarious","p":"adj","d":"không ổn định, bấp bênh","e":"The precarious situation required careful handling.","ev":"Tình huống không ổn định đòi hỏi sự xử lý cẩn thận.","k":"precarious"},{"t":"raze","p":"verb","d":"san bằng, phá hủy hoàn toàn","e":"They decided to raze the old building.","ev":"Họ quyết định san bằng tòa nhà cũ.","k":"raze"},{"t":"serendipity","p":"noun","d":"may mắn","e":"Their encounter was a stroke of serendipity.","ev":"Cuộc gặp gỡ của họ là một sự tình cờ may mắn.","k":"serendipity"},{"t":"spartan","p":"adj","d":"đơn giản","e":"He lived a spartan lifestyle, free of excess.","ev":"Anh ta sống một cuộc sống khắc khổ, không có sự dư thừa.","k":"spartan"},{"t":"vanquish","p":"verb","d":"đánh bại, chiến thắng","e":"They aimed to vanquish their opponents.","ev":"Họ nhằm mục đích đánh bại đối thủ.","k":"vanquish"},{"t":"vigilant","p":"adj","d":"cảnh giác, thận trọng","e":"She remained vigilant during the night.","ev":"Cô ấy luôn cảnh giác suốt đêm.","k":"vigilant"},{"t":"vindictive","p":"adj","d":"thù hận, báo oán","e":"His vindictive nature made it hard to trust him.","ev":"Bản chất trả thù của anh ta khiến việc tin tưởng khó khăn.","k":"vindictive"},{"t":"virulent","p":"adj","d":"độc hại, cực kì nguy hiểm","e":"The virus was particularly virulent this season.","ev":"Virus này đặc biệt mạnh mẽ trong mùa này.","k":"virulent"}]},{"n":"Buổi 26","c":[{"t":"abase","p":"verb","d":"hạ thấp, làm giảm phẩm giá","e":"After being overthrown and abased, the deposed leader bowed down to his conqueror.","ev":"Sau khi bị lật đổ và bị hạ thấp, nhà lãnh đạo bị truất quyền đã quỳ xuống trước kẻ chinh phục.","k":"abase"},{"t":"abate","p":"verb","d":"giảm bớt, hạ xuống","e":"The rain poured down for a while, then abated.","ev":"Cơn mưa đổ xuống trong một thời gian, sau đó giảm đi.","k":"abate"},{"t":"abdicate","p":"verb","d":"thoái vị, từ bỏ quyền lực","e":"When he realized the revolutionaries would win, the king abdicated his throne.","ev":"Khi nhận ra rằng những người cách mạng sẽ thắng, nhà vua đã từ bỏ ngai vàng.","k":"abdicate"},{"t":"abduct","p":"verb","d":"bắt cóc","e":"The evildoers abducted the fairy princess from her happy home.","ev":"Những kẻ xấu đã bắt cóc công chúa tiên từ ngôi nhà hạnh phúc của cô.","k":"abduct"},{"t":"aberration","p":"noun","d":"sự lệch lạc","e":"The Red Sox's 1918 World Series win was an aberration; they haven’t won since.","ev":"Chiến thắng World Series năm 1918 của Red Sox là một sự khác biệt; họ chưa bao giờ thắng kể từ đó.","k":"aberration"},{"t":"abet","p":"verb","d":"tiếp tay, khuyến khích","e":"The spy succeeded only because a friend on the inside abetted him.","ev":"Điệp viên thành công chỉ nhờ có một người bạn bên trong hỗ trợ.","k":"abet"},{"t":"abhor","p":"verb","d":"ghê tởm, căm ghét","e":"Oswald began to abhor soccer after constantly injuring himself while playing.","ev":"Oswald bắt đầu ghét bóng đá sau khi liên tục làm mình bị thương khi chơi.","k":"abhor"},{"t":"abide","p":"verb","d":"tuân theo, chịu đựng","e":"(1) Chuck decided to abide by the decision. (2) The mountains abide despite the weather.","ev":"(1) Chuck quyết định chấp nhận quyết định. (2) Những ngọn núi vẫn tồn tại bất chấp thời tiết.","k":"abide"},{"t":"abject","p":"adjective","d":"khổ sở, đáng thương","e":"After losing everything, Eloise felt abject.","ev":"Sau khi mất tất cả, Eloise cảm thấy khổ sở.","k":"abject"},{"t":"abjure","p":"verb","d":"từ bỏ, bác bỏ","e":"The President abjured the evil policies of his predecessor.","ev":"Tổng thống đã từ bỏ các chính sách xấu xa của người tiền nhiệm.","k":"abjure"},{"t":"abnegation","p":"noun","d":"sự từ chối, sự hy sinh","e":"The holy man practiced abnegation through simple living.","ev":"Người thánh thiện thực hành sự từ bỏ bằng cách sống đơn giản.","k":"abnegation"},{"t":"abort","p":"verb","d":"phá thai, hủy bỏ","e":"The men had to abort their plan to jump rope around the world after running out of food.","ev":"Những người đàn ông phải từ bỏ kế hoạch nhảy dây vòng quanh thế giới sau khi hết thức ăn.","k":"abort"},{"t":"abridge","p":"verb","d":"rút ngắn, lược bỏ","e":"(1) The publisher abridged the dictionary. (2) Even the abridged version is quite long.","ev":"(1) Nhà xuất bản đã rút gọn từ điển. (2) Ngay cả phiên bản rút gọn cũng khá dài.","k":"abridge"},{"t":"abrogate","p":"verb","d":"hủy bỏ, bãi bỏ","e":"The Bill of Rights ensures the government cannot abrogate our right to free press.","ev":"Luật biểu quyền đảm bảo rằng chính phủ không thể xóa bỏ quyền tự do báo chí của chúng ta.","k":"abrogate"},{"t":"abscond","p":"verb","d":"trốn thoát","e":"In the confusion, the super-spy absconded into the night with the secret plans.","ev":"Trong sự hoang mang, điệp viên siêu hạng đã lẩn trốn vào ban đêm cùng với các kế hoạch bí mật.","k":"abscond"},{"t":"absolution","p":"noun","d":"sự tha tội, sự giải thoát","e":"The jury gave Angela absolution with a verdict of not guilty.","ev":"Bồi thẩm đoàn đã cho Angela sự giải thoát với phán quyết không có tội.","k":"absolution"},{"t":"abstain","p":"verb","d":"kiêng cữ, nhịn","e":"Angus abstained from wearing the kilt despite pressure.","ev":"Angus đã từ chối mặc chiếc kilt mặc dù bị áp lực.","k":"abstain"},{"t":"abstruse","p":"adjective","d":"khó hiểu, bí ẩn","e":"John found geometry to be abstruse while others understood it easily.","ev":"John thấy hình học rất khó hiểu trong khi những người khác dễ dàng hiểu.","k":"abstruse"},{"t":"accede","p":"verb","d":"đồng ý, tán thành","e":"The teacher acceded to the class's request to play baseball instead of learning grammar.","ev":"Giáo viên đã đồng ý với yêu cầu của lớp để chơi bóng chày thay vì học ngữ pháp.","k":"accede"},{"t":"accentuate","p":"verb","d":"làm nổi bật, nhấn mạnh","e":"Psychologists say happy people accentuate the positive in life.","ev":"Các nhà tâm lý học nói rằng những người hạnh phúc làm nổi bật điều tích cực trong cuộc sống.","k":"accentuate"}]},{"n":"Buổi 27","c":[{"t":"accessible","p":"adjective","d":"có thể tiếp cận","e":"After studying hard, Marlena found her Ivy-League college goal was accessible.","ev":"Sau khi học chăm chỉ, Marlena nhận ra rằng mục tiêu vào đại học Ivy-League của cô là có thể đạt được.","k":"accessible"},{"t":"acclaim","p":"verb","d":"ca ngợi, hoan nghênh","e":"Greg’s poem won the acclaim of his friends.","ev":"Bài thơ của Greg đã nhận được sự khen ngợi từ bạn bè.","k":"acclaim"},{"t":"accolade","p":"noun","d":"giải thưởng, sự tán dương","e":"Everyone offered accolades to Sam after he won the Nobel Prize.","ev":"Mọi người đã gửi lời khen ngợi đến Sam sau khi anh ấy giành giải Nobel.","k":"accolade"},{"t":"accommodating","p":"adjective","d":"dễ tính, sẵn sàng giúp đỡ","e":"Arnold, Mark, and Zebulon were accommodating to each other despite their small apartment.","ev":"Arnold, Mark và Zebulon đã hỗ trợ lẫn nhau mặc dù căn hộ của họ nhỏ.","k":"accommodating"},{"t":"accord","p":"verb","d":"đồng ý, hòa hợp","e":"England and Iceland came to an accord about fishing rights after much negotiation.","ev":"Anh và Iceland đã đạt được thỏa thuận về quyền đánh bắt cá sau nhiều cuộc đàm phán.","k":"accord"},{"t":"accost","p":"verb","d":"tiếp cận, nói chuyện","e":"Antoinette accosted the waiter after he spilled soup on her for the fourth time.","ev":"Antoinette đã đối chất với người phục vụ sau khi anh ta làm đổ súp lên cô lần thứ tư.","k":"accost"},{"t":"accretion","p":"noun","d":"sự tích tụ, gia tăng","e":"Stalactites form through the accretion of minerals in caves.","ev":"Thạch nhũ hình thành qua sự tích lũy khoáng chất trong các hang động.","k":"accretion"},{"t":"acerbic","p":"adjective","d":"chua cay, sắc sảo","e":"Jill’s acerbic comments hurt her friends' feelings.","ev":"Những nhận xét châm chọc của Jill đã làm tổn thương cảm xúc của bạn bè.","k":"acerbic"},{"t":"acquiesce","p":"verb","d":"bằng lòng, chấp nhận","e":"Mr. Correlli acquiesced to his wife’s demand to come in for dinner.","ev":"Ông Correlli đã chấp nhận yêu cầu của vợ về việc vào ăn tối.","k":"acquiesce"},{"t":"acrimony","p":"noun","d":"sự cay đắng, sự chua chát","e":"Acrimony arose between Biff and Trevor after they both fell for Teresa.","ev":"Sự cay đắng phát sinh giữa Biff và Trevor sau khi cả hai đều phải lòng Teresa.","k":"acrimony"},{"t":"acumen","p":"noun","d":"sự nhạy bén, sự sắc sảo","e":"Larry’s mathematical acumen helped him solve problems quickly.","ev":"Sự nhạy bén toán học của Larry đã giúp anh giải quyết vấn đề nhanh chóng.","k":"acumen"},{"t":"acute","p":"adjective","d":"sắc bén, nhạy bén","e":"(1) Arnold could not walk due to acute pain. (2) Libby’s acute mind quickly solved the trick.","ev":"(1) Arnold không thể đi vì cơn đau dữ dội. (2) Trí thông minh nhạy bén của Libby đã nhanh chóng giải quyết được mẹo.","k":"acute"},{"t":"adamant","p":"adjective","d":"cứng rắn, kiên quyết","e":"The President remained adamant about his proposal despite public pressure.","ev":"Tổng thống vẫn kiên quyết về đề xuất của mình mặc dù có áp lực từ công chúng.","k":"adamant"},{"t":"adept","p":"adjective","d":"khéo léo, thành thạo","e":"Tarzan was adept at swinging from tree to tree.","ev":"Tarzan rất khéo léo trong việc đu từ cây này sang cây khác.","k":"adept"},{"t":"adhere","p":"verb","d":"tuân thủ, bám chặt","e":"(1) We adhered the poster to the wall. (2) He adhered to his religious beliefs without question.","ev":"(1) Chúng tôi đã dán áp phích lên tường. (2) Anh ta tuân thủ các tín ngưỡng tôn giáo của mình mà không cần nghi ngờ.","k":"adhere"},{"t":"admonish","p":"verb","d":"khiển trách, cảnh cáo","e":"Joe’s mother admonished him about eating cookies before dinner.","ev":"Mẹ của Joe đã nhắc nhở anh về việc ăn bánh quy trước bữa tối.","k":"admonish"},{"t":"adorn","p":"verb","d":"trang trí, tô điểm","e":"We adorned the tree with ornaments for the holiday.","ev":"Chúng tôi đã trang trí cây với những món đồ trang trí cho ngày lễ.","k":"adorn"},{"t":"adroit","p":"adjective","d":"khéo léo, tinh khôn","e":"The adroit thief went unnoticed as he picked pockets.","ev":"Kẻ trộm khéo léo đã không bị chú ý khi anh ta móc túi.","k":"adroit"},{"t":"adulation","p":"noun","d":"sự tán dương, sự nịnh bợ","e":"Marcy didn’t think the book deserved the adulation it received.","ev":"Marcy không nghĩ rằng cuốn sách xứng đáng với sự ca ngợi mà nó nhận được.","k":"adulation"},{"t":"adumbrate","p":"verb","d":"phác thảo, gợi ý","e":"The coach adumbrated a game plan, but it was unclear to the players.","ev":"Huấn luyện viên đã phác thảo một kế hoạch, nhưng nó không rõ ràng với các cầu thủ.","k":"adumbrate"}]},{"n":"Buổi 28","c":[{"t":"adverse","p":"adjective","d":"bất lợi, có hại","e":"The hikers abandoned their climb due to adverse conditions.","ev":"Những người đi bộ đã bỏ cuộc do điều kiện bất lợi.","k":"adverse"},{"t":"advocate","p":"verb","d":"ủng hộ, biện hộ","e":"(1) Arnold advocated for turning left at the stop sign. (2) He was a strong advocate for defense spending.","ev":"(1) Arnold đã ủng hộ việc rẽ trái tại biển báo dừng. (2) Anh là một người ủng hộ mạnh mẽ cho việc tăng cường chi tiêu quốc phòng.","k":"advocate"},{"t":"aerial","p":"adjective","d":"thuộc về không khí","e":"The fighter planes conducted impressive aerial maneuvers.","ev":"Các máy bay chiến đấu đã thực hiện các động tác trên không ấn tượng.","k":"aerial"},{"t":"aesthetic","p":"adjective","d":"thẩm mỹ, nghệ thuật","e":"We hired Susan for her excellent aesthetic sense in decorating.","ev":"Chúng tôi đã thuê Susan vì khả năng thẩm mỹ tuyệt vời của cô trong việc trang trí.","k":"aesthetic"},{"t":"affable","p":"adjective","d":"niềm nở, thân thiện","e":"People enjoy being around George because he is so affable.","ev":"Mọi người thích ở bên George vì anh ấy rất thân thiện.","k":"affable"},{"t":"affinity","p":"noun","d":"sự đồng cảm, sự hấp dẫn","e":"Jerry didn’t know why, but he felt an incredible affinity for Kramer the first time they met.","ev":"Jerry không biết tại sao, nhưng anh cảm thấy một mối liên hệ đặc biệt với Kramer lần đầu họ gặp nhau.","k":"affinity"},{"t":"affluent","p":"adjective","d":"giàu có, thịnh vượng","e":"Mrs. Grebelski was affluent, owning a huge house, three cars, and an island near Maine.","ev":"Bà Grebelski giàu có, sở hữu một ngôi nhà lớn, ba chiếc xe và một hòn đảo gần Maine.","k":"affluent"},{"t":"affront","p":"noun","d":"sự xúc phạm, sự lăng mạ","e":"Bernardo was very touchy, and took any slight as an affront to his honor.","ev":"Bernardo rất nhạy cảm, và coi bất kỳ sự xúc phạm nào là một sự sỉ nhục đối với danh dự của mình.","k":"affront"},{"t":"aggrandize","p":"verb","d":"phóng đại, làm cho lớn hơn","e":"Joseph always dropped the names of the famous people his father knew as a way to aggrandize his personal stature.","ev":"Joseph thường nhắc đến tên của những người nổi tiếng mà cha anh biết như một cách để nâng cao vị thế cá nhân của mình.","k":"aggrandize"},{"t":"aggregate","p":"noun","d":"tổng hợp, tổng số","e":"(1) The three branches of the U.S. Government form an aggregate much more powerful than its individual parts. (2) The dictator tried to aggregate as many people into his army as he possibly could.","ev":"(1) Ba nhánh của Chính phủ Hoa Kỳ tạo thành một tổng thể mạnh mẽ hơn nhiều so với từng phần riêng lẻ. (2) Nhà độc tài cố gắng tập hợp càng nhiều người vào quân đội của mình càng tốt.","k":"aggregate"},{"t":"aggrieved","p":"adjective","d":"bị thiệt thòi, bị xúc phạm","e":"The foreman mercilessly overworked his aggrieved employees.","ev":"Người giám sát đã làm việc quá sức với các nhân viên bị tổn thương của mình.","k":"aggrieved"},{"t":"agile","p":"adjective","d":"nhanh nhẹn, linh hoạt","e":"The dogs were too slow to catch the agile rabbit.","ev":"Những chú chó quá chậm để bắt kịp con thỏ nhanh nhẹn.","k":"agile"},{"t":"agnostic","p":"noun","d":"người hoài nghi về tôn giáo","e":"Joey’s parents are very religious, but he is agnostic.","ev":"Cha mẹ của Joey rất tôn giáo, nhưng anh thì không chắc chắn về sự tồn tại của Chúa.","k":"agnostic"},{"t":"agriculture","p":"noun","d":"nông nghiệp","e":"It was a huge step in the progress of civilization when tribes began to develop agriculture.","ev":"Đó là một bước lớn trong tiến bộ của nền văn minh khi các bộ tộc bắt đầu phát triển nông nghiệp.","k":"agriculture"},{"t":"aisle","p":"noun","d":"lối đi, lối giữa","e":"Once we got inside the stadium we walked down the aisle to our seats.","ev":"Khi chúng tôi vào trong sân vận động, chúng tôi đi xuống lối đi đến chỗ ngồi của mình.","k":"aisle"},{"t":"alacrity","p":"noun","d":"sự nhanh nhẹn, sự sẵn sàng","e":"Chuck loved to help his mother with alacrity whenever he could.","ev":"Chuck thích giúp mẹ mình với sự nhiệt tình bất cứ khi nào có thể.","k":"alacrity"},{"t":"alias","p":"noun","d":"bí danh, tên khác","e":"He snuck past the guards by using an alias and fake ID.","ev":"Anh đã lén lút vượt qua các lính gác bằng cách sử dụng một tên giả và giấy tờ giả.","k":"alias"},{"t":"allay","p":"verb","d":"làm dịu, giảm bớt","e":"The chairman of the Federal Reserve gave a speech to allay investors’ fears about an economic downturn.","ev":"Chủ tịch của Cục Dự trữ Liên bang đã có một bài phát biểu để xoa dịu nỗi lo sợ của các nhà đầu tư về một cuộc suy thoái kinh tế.","k":"allay"},{"t":"allege","p":"verb","d":"cáo buộc, khẳng định","e":"The policeman alleged that Marshall committed the crime, but he was set free after the investigation turned up no evidence.","ev":"Cảnh sát cáo buộc rằng Marshall đã phạm tội, nhưng sau khi điều tra không tìm thấy bằng chứng, Marshall được thả.","k":"allege"},{"t":"alleviate","p":"verb","d":"giảm nhẹ, làm dịu","e":"This drug will alleviate the symptoms of the terrible disease, but only for a while.","ev":"Thuốc này sẽ làm giảm triệu chứng của căn bệnh khủng khiếp, nhưng chỉ trong một thời gian ngắn.","k":"alleviate"}]},{"n":"Buổi 29","c":[{"t":"allocate","p":"verb","d":"phân bổ, chia sẻ","e":"The Mayor allocated 30 percent of the funds for improving the town’s schools.","ev":"Thị trưởng đã phân bổ 30% quỹ để cải thiện các trường học của thị trấn.","k":"allocate"},{"t":"aloof","p":"adjective","d":"tách biệt, lạnh lùng","e":"The scientist could seem aloof, as if he didn’t care about his friends, but he was just thinking about quantum mechanics.","ev":"Nhà khoa học có thể có vẻ xa cách, như thể ông không quan tâm đến bạn bè, nhưng thực ra ông chỉ đang suy nghĩ về cơ học lượng tử.","k":"aloof"},{"t":"altercation","p":"noun","d":"cuộc cãi vã, tranh chấp","e":"Jason and Lionel blamed one another for the car accident, leading to an altercation.","ev":"Jason và Lionel đã đổ lỗi cho nhau về vụ tai nạn xe hơi, dẫn đến một cuộc tranh cãi.","k":"altercation"},{"t":"amalgamate","p":"verb","d":"hợp nhất, liên kết","e":"Because of his charisma, the candidate was able to amalgamate all Democrats and Republicans.","ev":"Nhờ sự quyến rũ của mình, ứng cử viên đã có thể hợp nhất tất cả các đảng viên Dân chủ và Cộng hòa.","k":"amalgamate"},{"t":"ambiguous","p":"adjective","d":"mơ hồ, không rõ ràng","e":"Some believe Caesar married Cleopatra for her power; others think it was her beauty. His actual reasons are ambiguous.","ev":"Một số người cho rằng Caesar kết hôn với Cleopatra vì quyền lực của cô; những người khác nghĩ rằng đó là vì sắc đẹp của cô.","k":"ambiguous"},{"t":"ambivalent","p":"adjective","d":"mâu thuẫn, cảm xúc hỗn hợp","e":"My feelings about Calvin are ambivalent because he is a loyal friend, but also a cruel thief.","ev":"Cảm xúc của tôi về Calvin là mâu thuẫn vì anh ấy là một người bạn trung thành, nhưng cũng là một kẻ trộm độc ác.","k":"ambivalent"},{"t":"ameliorate","p":"verb","d":"cải thiện, nâng cao","e":"The tense situation was ameliorated when Sam proposed a solution everyone could agree upon.","ev":"Tình huống căng thẳng đã được cải thiện khi Sam đề xuất một giải pháp mà mọi người có thể đồng ý.","k":"ameliorate"},{"t":"amenable","p":"adjective","d":"dễ tiếp thu, dễ bảo","e":"Our father was amenable when we asked him to drive us to the farm.","ev":"Cha chúng tôi đã dễ tính khi chúng tôi hỏi ông chở chúng tôi đến trang trại.","k":"amenable"},{"t":"amenity","p":"noun","d":"tiện nghi, sự thoải mái","e":"Bill Gates’s house is stocked with so many amenities, he never has to do anything for himself.","ev":"Nhà của Bill Gates có rất nhiều tiện nghi, ông không bao giờ phải làm gì cho chính mình.","k":"amenity"},{"t":"amiable","p":"adjective","d":"tốt bụng, thân thiện","e":"An amiable fellow, Harry got along with just about everyone.","ev":"Là một người thân thiện, Harry hòa hợp với hầu hết mọi người.","k":"amiable"},{"t":"amicable","p":"adjective","d":"hòa bình, thân ái","e":"Claudia and Jimmy got divorced, but amicably and without hard feelings.","ev":"Claudia và Jimmy đã ly hôn, nhưng hòa thuận và không có cảm giác khó chịu.","k":"amicable"},{"t":"amorous","p":"adjective","d":"yêu đương, tình cảm","e":"Whenever Albert saw Mariah in her slinky red dress, he felt quite amorous.","ev":"Mỗi khi Albert thấy Mariah trong chiếc đầm đỏ quyến rũ, anh cảm thấy rất say đắm.","k":"amorous"},{"t":"amorphous","p":"adjective","d":"vô định hình, không có hình dạng","e":"The effort was doomed from the start because the reasons behind it were amorphous.","ev":"Nỗ lực đã bị thất bại ngay từ đầu vì lý do phía sau nó không rõ ràng.","k":"amorphous"},{"t":"anachronistic","p":"adjective","d":"lỗi thời, không phù hợp với thời gian","e":"Saying that the Pyramids were built after the Titanic sank is anachronistic.","ev":"Nói rằng các Kim tự tháp được xây dựng sau khi Titanic chìm là sai thứ tự thời gian.","k":"anachronistic"},{"t":"analgesic","p":"noun","d":"thuốc giảm đau","e":"Put this analgesic on the wound so that the poor man feels a little better.","ev":"Đặt thuốc giảm đau này lên vết thương để người đàn ông tội nghiệp cảm thấy dễ chịu hơn một chút.","k":"analgesic"},{"t":"analogous","p":"adjective","d":"tương tự, giống nhau","e":"The bone structure of whales and fish is quite analogous, even though they are unrelated.","ev":"Cấu trúc xương của cá voi và cá rất tương tự, mặc dù chúng không có quan hệ di truyền.","k":"analogous"},{"t":"anarchist","p":"noun","d":"người theo chủ nghĩa vô chính phủ","e":"An anarchist, Carmine wanted to dissolve every government everywhere.","ev":"Là một kẻ vô chính phủ, Carmine muốn giải thể mọi chính phủ trên khắp nơi.","k":"anarchist"},{"t":"anathema","p":"noun","d":"điều bị ghét, sự nguyền rủa","e":"I never want to see that murderer. He is an anathema to me.","ev":"Tôi không bao giờ muốn thấy tên sát nhân đó. Hắn là một người tôi ghét bỏ.","k":"anathema"},{"t":"anecdote","p":"noun","d":"giai thoại, câu chuyện ngắn","e":"After dinner, Marlon told an anecdote about the time he got his nose stuck in a toaster.","ev":"Sau bữa tối, Marlon đã kể một câu chuyện hài hước về lần anh bị mũi kẹt vào máy nướng bánh.","k":"anecdote"},{"t":"anesthesia","p":"noun","d":"thuốc gây mê","e":"When the nerves in his spine were damaged, Mr. Hollins suffered anesthesia in his legs.","ev":"Khi các dây thần kinh trong cột sống của ông bị tổn thương, ông Hollins đã mất cảm giác ở chân.","k":"anesthesia"}]},{"n":"Buổi 30","c":[{"t":"anguish","p":"noun","d":"nỗi đau, sự đau khổ","e":"Angelos suffered terrible anguish when he learned that Buffy had died.","ev":"Angelos đã chịu đựng nỗi đau khổ khủng khiếp khi biết rằng Buffy đã chết.","k":"anguish"},{"t":"animated","p":"adjective","d":"sống động, nhộn nhịp","e":"When he talks about drama, which is his true passion, he becomes very animated.","ev":"Khi anh nói về kịch, niềm đam mê thực sự của mình, anh trở nên rất sinh động.","k":"animated"},{"t":"annex","p":"verb","d":"sáp nhập, bổ sung","e":"(1) After defeating them in battle, the Russians annexed Poland. (2) He likes to study in a little annex attached to the library.","ev":"(1) Sau khi đánh bại họ trong trận chiến, người Nga đã sát nhập Ba Lan. (2) Anh thích học trong một phòng phụ nhỏ nối với thư viện.","k":"annex"},{"t":"annul","p":"verb","d":"hủy bỏ, bãi bỏ","e":"Congress sought to annul the law after its catastrophic effects became evident.","ev":"Quốc hội đã tìm cách hủy bỏ luật này sau khi các tác động thảm khốc của nó trở nên rõ ràng.","k":"annul"},{"t":"anomaly","p":"noun","d":"sự bất thường, điều khác thường","e":"That rip in the space-time continuum is certainly a spatial anomaly.","ev":"Vết rách trong không-thời gian đó chắc chắn là một bất thường không gian.","k":"anomaly"},{"t":"anonymous","p":"adjective","d":"ẩn danh, không rõ tên","e":"Mary received a love poem from an anonymous admirer.","ev":"Mary nhận được một bài thơ tình từ một người hâm mộ ẩn danh.","k":"anonymous"},{"t":"antagonism","p":"noun","d":"sự đối kháng, sự chống đối","e":"Superman and Bizarro Superman shared a mutual antagonism, and often fought.","ev":"Superman và Bizarro Superman có sự thù địch lẫn nhau và thường xuyên chiến đấu.","k":"antagonism"},{"t":"antecedent","p":"noun","d":"cái đi trước, tiền đề","e":"The great tradition of Western culture had its antecedent in the culture of Ancient Greece.","ev":"Truyền thống vĩ đại của văn hóa phương Tây có nguồn gốc từ nền văn hóa Hy Lạp cổ đại.","k":"antecedent"},{"t":"antediluvian","p":"adjective","d":"cổ xưa, trước thời đại hồng thủy","e":"The antediluvian man still believed that Eisenhower was president of the United States.","ev":"Người cổ đại đó vẫn tin rằng Eisenhower là tổng thống của Hoa Kỳ.","k":"antediluvian"},{"t":"anthology","p":"noun","d":"tuyển tập","e":"The new anthology of Bob Dylan songs contains all his greatest hits.","ev":"Tuyển tập mới về các bài hát của Bob Dylan chứa tất cả những bản hit lớn nhất của ông.","k":"anthology"},{"t":"antipathy","p":"noun","d":"sự ác cảm, sự thù ghét","e":"I feel nothing but antipathy for you because you are a liar and a thief.","ev":"Tôi không cảm thấy gì ngoài sự ghê tởm với bạn vì bạn là một kẻ nói dối và ăn cắp.","k":"antipathy"},{"t":"antiquated","p":"adjective","d":"lỗi thời, cổ hủ","e":"That antiquated car has none of the modern features like power windows.","ev":"Chiếc xe cổ đó không có bất kỳ tính năng hiện đại nào như cửa sổ điện.","k":"antiquated"},{"t":"antiseptic","p":"adjective","d":"khử trùng, sát trùng","e":"The antiseptic hospital was very bare, but its cleanliness helped to keep patients healthy.","ev":"Bệnh viện khử trùng rất đơn giản, nhưng sự sạch sẽ của nó đã giúp giữ cho bệnh nhân khỏe mạnh.","k":"antiseptic"},{"t":"antithesis","p":"noun","d":"sự đối lập, sự tương phản","e":"Your values, which hold war in high esteem, are the antithesis of my pacifist beliefs.","ev":"Giá trị của bạn, coi trọng chiến tranh, hoàn toàn trái ngược với niềm tin hòa bình của tôi.","k":"antithesis"},{"t":"anxiety","p":"noun","d":"sự lo âu, sự lo lắng","e":"When he heard about the car crash, he felt anxiety because he knew his girlfriend was driving on that road.","ev":"Khi anh nghe về vụ tai nạn xe hơi, anh cảm thấy lo lắng vì biết bạn gái mình đang lái xe trên con đường đó.","k":"anxiety"},{"t":"apathetic","p":"adjective","d":"thờ ơ, không quan tâm","e":"Bruno was apathetic about whether he lived under a capitalist or communist regime.","ev":"Bruno không quan tâm đến việc mình sống dưới chế độ tư bản hay cộng sản.","k":"apathetic"},{"t":"apocryphal","p":"adjective","d":"không rõ nguồn gốc, có thể là giả","e":"The stories about my demise were apocryphal, as I am standing before you.","ev":"Những câu chuyện về cái chết của tôi là giả mạo, vì tôi đang đứng trước mặt bạn.","k":"apocryphal"},{"t":"appalling","p":"adjective","d":"gây kinh hãi, kinh khủng","e":"The judge found the murderer’s crimes appalling.","ev":"Thẩm phán thấy tội ác của kẻ sát nhân thật kinh khủng.","k":"appalling"},{"t":"appease","p":"verb","d":"xoa dịu, làm hài lòng","e":"The mother gave her child candy to appease him when he cried.","ev":"Người mẹ đã cho đứa trẻ kẹo để làm dịu nó khi nó khóc.","k":"appease"},{"t":"appraise","p":"verb","d":"đánh giá, ước lượng","e":"A realtor will come over tonight to appraise our house.","ev":"Một nhân viên bất động sản sẽ đến tối nay để định giá ngôi nhà của chúng tôi.","k":"appraise"}]},{"n":"Buổi 31","c":[{"t":"apprehend","p":"verb","d":"bắt giữ, nhận thức","e":"(1) The criminal was apprehended at the scene. (2) The student had trouble apprehending math concepts.","ev":"(1) Tên tội phạm đã bị bắt giữ tại hiện trường. (2) Học sinh gặp khó khăn trong việc hiểu các khái niệm toán học.","k":"apprehend"},{"t":"approbation","p":"noun","d":"sự tán thành, sự phê duyệt","e":"The crowd welcomed the heroes with approbation.","ev":"Đám đông đã chào đón các anh hùng với sự ca ngợi.","k":"approbation"},{"t":"appropriate","p":"adjective","d":"thích hợp, phù hợp","e":"The government appropriated the farmer’s land without justification.","ev":"Chính phủ đã chiếm đoạt đất của nông dân mà không có lý do chính đáng.","k":"appropriate"},{"t":"aquatic","p":"adjective","d":"thuộc về nước, sống dưới nước","e":"The marine biologist studies aquatic creatures like starfish.","ev":"Nhà sinh vật học biển nghiên cứu các sinh vật dưới nước như sao biển.","k":"aquatic"},{"t":"arable","p":"adjective","d":"có thể canh tác, trồng trọt","e":"The farmer purchased a plot of arable land for corn.","ev":"Người nông dân đã mua một mảnh đất canh tác để trồng ngô.","k":"arable"},{"t":"arbiter","p":"noun","d":"người phân xử, trọng tài","e":"The divorce court judge will serve as the arbiter between the estranged husband and wife.","ev":"Thẩm phán tòa án ly hôn sẽ đóng vai trò làm trọng tài giữa hai vợ chồng ly thân.","k":"arbiter"},{"t":"arbitrary","p":"adjective","d":"tùy ý, tùy tiện","e":"The boy’s decision to choose one college seems arbitrary.","ev":"Quyết định của cậu bé chọn một trường đại học dường như là ngẫu nhiên.","k":"arbitrary"},{"t":"arbitration","p":"noun","d":"sự phân xử","e":"The employee sought arbitration when he could not resolve a disagreement with his supervisor.","ev":"Nhân viên đã yêu cầu trọng tài khi không thể giải quyết mâu thuẫn với cấp trên của mình.","k":"arbitration"},{"t":"arboreal","p":"adjective","d":"thuộc về cây cối, sống trên cây","e":"Leaves and roots are a few arboreal traits.","ev":"Lá và rễ là một vài đặc điểm liên quan đến cây.","k":"arboreal"},{"t":"arcane","p":"adjective","d":"bí mật, khó hiểu","e":"The professor is an expert in arcane Lithuanian literature.","ev":"Giáo sư là chuyên gia về văn học Lithuania bí ẩn.","k":"arcane"},{"t":"archaic","p":"adjective","d":"cổ xưa, lỗi thời","e":"In some regions, an archaic Chinese dialect is still spoken.","ev":"Ở một số vùng, một phương ngữ tiếng Trung cổ vẫn được nói.","k":"archaic"},{"t":"archetypal","p":"adjective","d":"nguyên mẫu, mẫu mực","e":"Some believe George Washington was the archetypal politician.","ev":"Một số người cho rằng George Washington là hình mẫu điển hình của một chính trị gia.","k":"archetypal"},{"t":"ardor","p":"noun","d":"sự nhiệt tình, đam mê","e":"The soldiers conveyed their ardor with impassioned battle cries.","ev":"Các chiến sĩ thể hiện nhiệt huyết của họ bằng những tiếng hò reo trong trận chiến.","k":"ardor"},{"t":"arid","p":"adjective","d":"khô cằn, thiếu nước","e":"Little grows successfully in arid environments.","ev":"Rất ít cây cối phát triển thành công trong môi trường khô cằn.","k":"arid"},{"t":"arrogate","p":"verb","d":"đòi quyền, chiếm đoạt","e":"The king arrogated the right to order executions to himself.","ev":"Vị vua đã tự cho mình quyền ra lệnh thi hành án tử.","k":"arrogate"},{"t":"artifact","p":"noun","d":"hiện vật, đồ tạo tác","e":"The scientists searched the cave for artifacts from the ancient Mayan civilization.","ev":"Các nhà khoa học đã tìm kiếm trong hang động để tìm các di tích từ nền văn minh Maya cổ đại.","k":"artifact"},{"t":"artisan","p":"noun","d":"thợ thủ công","e":"The artisan uses wood to create beautiful furniture.","ev":"Người thợ thủ công sử dụng gỗ để tạo ra đồ nội thất đẹp.","k":"artisan"},{"t":"ascertain","p":"verb","d":"xác định, làm rõ","e":"The student ascertained that some plants can survive for weeks without water.","ev":"Học sinh đã nhận ra rằng một số loại cây có thể sống sót nhiều tuần mà không có nước.","k":"ascertain"},{"t":"ascetic","p":"adjective","d":"khổ hạnh, khắc khổ","e":"The ascetic monk lived a life devoid of worldly pleasures.","ev":"Thầy tu khổ hạnh sống một cuộc đời không có những thú vui trần thế.","k":"ascetic"},{"t":"ascribe","p":"verb","d":"quy cho, gán cho","e":"Many ascribe the invention of dynamite to Alfred Nobel.","ev":"Nhiều người cho rằng việc phát minh ra thuốc nổ là của Alfred Nobel.","k":"ascribe"}]},{"n":"Buổi 32","c":[{"t":"aspersion","p":"noun","d":"sự vu khống, sự phỉ báng","e":"The politicians cast aspersions on each other's character.","ev":"Các chính trị gia đã chỉ trích lẫn nhau về phẩm chất.","k":"aspersion"},{"t":"aspire","p":"verb","d":"khao khát, mong muốn","e":"The young artist aspires to showcase her work in a gallery.","ev":"Nghệ sĩ trẻ khao khát được trưng bày tác phẩm của mình trong một phòng tranh.","k":"aspire"},{"t":"assail","p":"verb","d":"tấn công, công kích","e":"The soldiers assailed the enemy's position at dawn.","ev":"Các chiến sĩ đã tấn công vị trí của kẻ thù vào lúc bình minh.","k":"assail"},{"t":"assess","p":"verb","d":"đánh giá, định giá","e":"The committee will assess the situation before making a decision.","ev":"Ủy ban sẽ đánh giá tình hình trước khi đưa ra quyết định.","k":"assess"},{"t":"assiduous","p":"adjective","d":"cần cù, siêng năng","e":"The students were assiduous in their preparation for the exams.","ev":"Các sinh viên đã chăm chỉ trong việc chuẩn bị cho các kỳ thi.","k":"assiduous"},{"t":"assuage","p":"verb","d":"làm dịu, xoa dịu","e":"The mother tried to assuage her child's fears after the nightmare.","ev":"Người mẹ đã cố gắng làm dịu nỗi sợ hãi của con mình sau cơn ác mộng.","k":"assuage"},{"t":"astute","p":"adjective","d":"sắc sảo, thông minh","e":"The astute businessman quickly adapted to the changing market.","ev":"Doanh nhân khôn ngoan đã nhanh chóng thích ứng với thị trường đang thay đổi.","k":"astute"},{"t":"asylum","p":"noun","d":"nơi ẩn náu, tị nạn","e":"(1) The forest served as an asylum from the pressures of city life. (2) After his diagnosis, he was admitted to an asylum.","ev":"(1) Rừng rậm là nơi trú ẩn khỏi áp lực của cuộc sống thành phố. (2) Sau khi được chẩn đoán, ông đã được đưa vào một viện tâm thần.","k":"asylum"},{"t":"atone","p":"verb","d":"chuộc lỗi, đền bù","e":"She wanted to atone for her past mistakes by helping others.","ev":"Cô ấy muốn chuộc lỗi cho những sai lầm trong quá khứ bằng cách giúp đỡ người khác.","k":"atone"},{"t":"atrophy","p":"verb","d":"teo lại, suy giảm","e":"Muscles can atrophy without regular exercise.","ev":"Các cơ có thể bị teo nếu không tập thể dục thường xuyên.","k":"atrophy"},{"t":"attain","p":"verb","d":"đạt được, giành được","e":"She worked hard to attain her goal of becoming a doctor.","ev":"Cô ấy đã làm việc chăm chỉ để đạt được mục tiêu trở thành bác sĩ.","k":"attain"},{"t":"attribute","p":"(1) verb; (2) noun","d":"(1) to credit, assign; (2) a facet or trait","e":"(1) He attributes all of his success to his mother’s encouragement. \n (2) The beetle’s most peculiar attributes include its thorny eyes.","ev":"(1) Anh cho rằng tất cả thành công của mình là nhờ sự khuyến khích của mẹ. \n (2) Một trong những đặc điểm kỳ lạ nhất của con bọ là mắt nhô ra có gai.","k":"attribute"},{"t":"atypical","p":"adj.","d":"not typical, unusual","e":"Screaming and crying is atypical adult behavior.","ev":"La hét và khóc không phải là hành vi bình thường của người lớn.","k":"atypical"},{"t":"audacious","p":"adj.","d":"excessively bold","e":"The security guard was shocked by the fan’s audacious attempt to bribe him.","ev":"Nhân viên bảo vệ đã sốc trước nỗ lực táo bạo của người hâm mộ khi hối lộ anh.","k":"audacious"},{"t":"audible","p":"adj.","d":"able to be heard","e":"The missing person’s shouts were not audible.","ev":"Những tiếng kêu cứu của người mất tích thì không nghe thấy.","k":"audible"},{"t":"augment","p":"verb","d":"to add to, expand","e":"The student seeks to augment his knowledge of French by reading literature.","ev":"Sinh viên đó muốn mở rộng kiến thức tiếng Pháp bằng cách đọc văn học.","k":"augment"},{"t":"auspicious","p":"adj.","d":"favorable, indicative of good things","e":"The sunny forecast was an auspicious sign for her match.","ev":"Dự báo nắng đẹp là dấu hiệu thuận lợi cho trận đấu của cô.","k":"auspicious"},{"t":"austere","p":"adj.","d":"very bare, bleak","e":"The austere furniture in the abandoned house made it feel haunted.","ev":"Đồ nội thất đơn giản trong ngôi nhà bị bỏ hoang khiến nó cảm thấy ám ảnh.","k":"austere"},{"t":"avarice","p":"noun","d":"excessive greed","e":"The banker’s avarice led him to amass a great fortune.","ev":"Lòng tham của ngân hàng đã khiến ông tích lũy được một khối tài sản lớn.","k":"avarice"},{"t":"avenge","p":"verb","d":"to seek revenge","e":"The victims strive to avenge themselves against their robbers.","ev":"Các nạn nhân cố gắng báo thù những kẻ cướp của mình.","k":"avenge"}]},{"n":"Buổi 33","c":[{"t":"aversion","p":"noun","d":"a particular dislike for something","e":"Ben has an aversion to cold climates due to his Hawaiian roots.","ev":"Vì xuất thân từ Hawaii, Ben rất ghét những vùng khí hậu lạnh.","k":"aversion"},{"t":"balk","p":"verb","d":"to stop, block abruptly","e":"Edna’s boss balked at her request for a raise.","ev":"Sếp của Edna đã từ chối yêu cầu tăng lương của cô.","k":"balk"},{"t":"ballad","p":"noun","d":"a love song","e":"Greta’s boyfriend played her a ballad during their walk.","ev":"Bạn trai của Greta đã chơi cho cô một bài ballad trong khi đi dạo.","k":"ballad"},{"t":"banal","p":"adj.","d":"dull, commonplace","e":"The client rejected the proposal because it seemed banal.","ev":"Khách hàng đã từ chối đề xuất vì thấy nó tẻ nhạt.","k":"banal"},{"t":"bane","p":"noun","d":"a burden","e":"Advanced physics is the bane of many students’ lives.","ev":"Vật lý nâng cao là gánh nặng của nhiều sinh viên.","k":"bane"},{"t":"bard","p":"noun","d":"a poet, often a singer","e":"Shakespeare is often considered the greatest bard in English history.","ev":"Shakespeare thường được coi là nhà thơ vĩ đại nhất trong lịch sử tiếng Anh.","k":"bard"},{"t":"bashful","p":"adj.","d":"shy, excessively timid","e":"Frankie’s mother told him not to be bashful at the party.","ev":"Mẹ của Frankie bảo cậu đừng ngại ngùng khi tham gia bữa tiệc.","k":"bashful"},{"t":"battery","p":"(1) noun; (2) noun","d":"(1) a device that supplies power; (2) assault","e":"(1) Most cars run on a battery and gasoline. \n (2) He was accused of assault and battery.","ev":"(1) Hầu hết các xe ô tô chạy bằng ắc quy và xăng. \n (2) Anh bị cáo buộc tấn công và đánh đập.","k":"battery"},{"t":"beguile","p":"verb","d":"to trick, deceive","e":"The thief beguiled his partners into surrendering their money.","ev":"Kẻ trộm đã lừa dối các đồng phạm giao nộp tiền của họ.","k":"beguile"},{"t":"behemoth","p":"noun","d":"something of tremendous power or size","e":"The new aircraft carrier is among the behemoths added to the fleet.","ev":"Tàu sân bay mới là một trong những “quái vật” được thêm vào đội hình.","k":"behemoth"},{"t":"benevolent","p":"adj.","d":"marked by goodness","e":"Police officers should be commended for their benevolent service.","ev":"Các sĩ quan cảnh sát nên được khen ngợi vì dịch vụ tốt đẹp của họ.","k":"benevolent"},{"t":"benign","p":"adj.","d":"favorable, not threatening","e":"The tests determined her tumor was benign.","ev":"Các xét nghiệm đã xác định rằng khối u của cô là lành tính.","k":"benign"},{"t":"bequeath","p":"verb","d":"to pass on, give","e":"Jon’s father bequeathed his estate to his mother.","ev":"Cha của Jon đã để lại tài sản cho mẹ của cậu.","k":"bequeath"},{"t":"berate","p":"verb","d":"to scold vehemently","e":"The boss berated his employees for missing the deadline.","ev":"Sếp đã quở trách nhân viên vì không hoàn thành đúng thời hạn.","k":"berate"},{"t":"bereft","p":"adj.","d":"devoid of, without","e":"His family was bereft of food after the tornado.","ev":"Gia đình anh thiếu thốn thực phẩm sau cơn lốc xoáy.","k":"bereft"},{"t":"beseech","p":"verb","d":"to beg, plead, implore","e":"The servant beseeched the king for food.","ev":"Người hầu đã cầu xin nhà vua cho thức ăn.","k":"beseech"},{"t":"bias","p":"noun","d":"a tendency, inclination, prejudice","e":"The judge’s bias against smokers influenced his decision.","ev":"Thành kiến của thẩm phán đối với người hút thuốc đã ảnh hưởng đến quyết định của ông.","k":"bias"},{"t":"concomitant","p":"adjective","d":"đi kèm, phụ thuộc","e":"His dislike of hard work carried with it a concomitant lack of funds.","ev":"Sự lười biếng của anh ấy dẫn đến việc thiếu tiền như một hệ quả.","k":"concomitant"},{"t":"concord","p":"noun","d":"sự đồng thuận, hòa hợp","e":"Julie and Harold began the evening with a disagreement but ended it in a state of perfect concord.","ev":"Họ đã giải quyết xung đột và tìm thấy sự đồng thuận.","k":"concord"},{"t":"condolence","p":"noun","d":"sự chia buồn","e":"Brian lamely offered his condolences on the loss of his sister’s roommate’s cat.","ev":"Brian đã bày tỏ sự cảm thông về cái chết của một con mèo.","k":"condolence"}]},{"n":"Buổi 34","c":[{"t":"condone","p":"verb","d":"tha thứ, bỏ qua","e":"He refused to condone his brother’s crime.","ev":"Anh không tha thứ hay biện hộ cho hành động sai trái của em trai.","k":"condone"},{"t":"conduit","p":"noun","d":"ống dẫn","e":"The water flowed through the conduit into the container.","ev":"Nước chảy qua ống dẫn vào một khu vực khác.","k":"conduit"},{"t":"confection","p":"noun","d":"món ngọt, món tráng miệng","e":"We went to the mall food court and purchased a delicious confection.","ev":"Họ đã mua một món tráng miệng ngon tại khu ẩm thực.","k":"confection"},{"t":"confidant","p":"noun","d":"người được tin tưởng","e":"Shortly after we met, she became my chief confidant.","ev":"Cô ấy được tin tưởng giữ những bí mật cá nhân.","k":"confidant"},{"t":"conflagration","p":"noun","d":"hỏa hoạn lớn","e":"The conflagration consumed the entire building.","ev":"Ngọn lửa lớn đã thiêu rụi toàn bộ công trình.","k":"conflagration"},{"t":"confluence","p":"noun","d":"sự hội tụ, sự kết hợp","e":"A confluence of different factors made tonight the perfect night.","ev":"Nhiều lý do đã tụ họp lại tạo ra một buổi tối đặc biệt.","k":"confluence"},{"t":"conformist","p":"noun","d":"người tuân thủ, người có tính bảo thủ","e":"Julian was such a conformist that he had to wait and see if his friends would do something before he would commit.","ev":"Anh chỉ hành động sau khi thấy người khác làm gì.","k":"conformist"},{"t":"confound","p":"verb","d":"làm bối rối, làm khó khăn","e":"MacGuyver confounded the policemen pursuing him by covering his tracks.","ev":"Anh đã làm cho cảnh sát bối rối và trốn thoát.","k":"confound"},{"t":"congeal","p":"verb","d":"đặc lại, đông lại","e":"The sauce had congealed into a thick paste.","ev":"Nước sốt đã trở thành một hỗn hợp đặc và rắn.","k":"congeal"},{"t":"congenial","p":"adjective","d":"dễ chịu, hòa hợp","e":"His congenial manner made him popular wherever he went.","ev":"Tính cách thân thiện của anh ấy thu hút nhiều bạn bè.","k":"congenial"},{"t":"congregation","p":"noun","d":"sự tập hợp, cộng đồng","e":"The priest told the congregation that he would be retiring.","ev":"Cộng đồng đã tụ họp để nghe thông báo tôn giáo.","k":"congregation"},{"t":"congruity","p":"noun","d":"sự phù hợp, sự đồng nhất","e":"Bill and Veronica achieved a perfect congruity of opinion.","ev":"Họ hoàn toàn đồng ý với nhau.","k":"congruity"},{"t":"connive","p":"verb","d":"âm thầm, lén lút","e":"She connived to get me to give up my vacation plans.","ev":"Cô ấy âm thầm lên kế hoạch để thay đổi kế hoạch của tôi.","k":"connive"},{"t":"consecrate","p":"verb","d":"thánh hiến, dành cho mục đích thiêng liêng","e":"Arvin consecrated his spare bedroom as a shrine to Christina.","ev":"Anh đã dành phòng dự trữ làm nơi thờ cúng.","k":"consecrate"},{"t":"consensus","p":"noun","d":"sự đồng thuận","e":"The jury was able to reach a consensus only after days of deliberation.","ev":"Bồi thẩm đoàn cuối cùng đã đồng ý sau nhiều cuộc thảo luận.","k":"consensus"},{"t":"consign","p":"verb","d":"giao phó, gửi gắm","e":"Unwillingly, he consigned his mother to a nursing home.","ev":"Anh đã phải gửi mẹ vào trại dưỡng lão.","k":"consign"},{"t":"consolation","p":"noun","d":"sự an ủi, sự động viên","e":"Darren found Alexandra’s presence to be a consolation for his suffering.","ev":"Sự có mặt của cô ấy giúp anh cảm thấy tốt hơn trong những lúc khó khăn.","k":"consolation"},{"t":"consonant","p":"adjective","d":"hòa hợp, phù hợp","e":"The singers’ consonant voices were beautiful.","ev":"Giọng hát của họ hòa quyện một cách hoàn hảo.","k":"consonant"},{"t":"constituent","p":"noun","d":"thành phần, yếu tố thiết yếu","e":"The most important constituent of her perfume is something called ambergris.","ev":"Ambergris là thành phần quan trọng trong nước hoa của cô ấy.","k":"constituent"},{"t":"constrain","p":"verb","d":"hạn chế, ràng buộc","e":"His belief in nonviolence constrained him from taking revenge on his attackers.","ev":"Nguyên tắc của anh đã ngăn cản anh trả thù.","k":"constrain"}]},{"n":"Buổi 35","c":[{"t":"construe","p":"verb","d":"giải thích","e":"He construed her throwing his clothes out the window as a signal that she wanted him to leave.","ev":"Anh đã diễn giải hành động của cô ấy như một dấu hiệu rằng cô ấy muốn anh rời đi.","k":"construe"},{"t":"consummate","p":"verb","d":"hoàn tất","e":"Erica and Donald consummated their agreement in the executive boardroom.","ev":"Họ đã hoàn tất thỏa thuận của mình trong một không gian riêng tư.","k":"consummate"},{"t":"consumption","p":"noun","d":"sự tiêu thụ","e":"Consumption of intoxicating beverages is not permitted on these premises.","ev":"Việc uống rượu bị cấm trong khu vực này.","k":"consumption"},{"t":"contemporaneous","p":"adjective","d":"cùng thời, đồng thời","e":"Though her novels do not feature the themes of Romanticism, Jane Austen’s work was contemporaneous with that of Wordsworth and Byron.","ev":"Tác phẩm của Austen diễn ra trong cùng một thời kỳ văn học với các tác giả này.","k":"contemporaneous"},{"t":"contentious","p":"adjective","d":"hay tranh cãi","e":"George’s contentious personality made him unpopular with his classmates.","ev":"Tính cách tranh cãi của anh khiến anh không được bạn bè yêu thích.","k":"contentious"},{"t":"contravene","p":"verb","d":"vi phạm, trái ngược","e":"Edwidge contravened his landlady’s rule against overnight guests.","ev":"Anh đã vi phạm quy định của bà chủ nhà về khách qua đêm.","k":"contravene"},{"t":"contrite","p":"adjective","d":"ăn năn, hối hận","e":"Blake’s contrite behavior made it impossible to stay angry at him.","ev":"Hành động ăn năn của anh khiến mọi người dễ dàng tha thứ cho anh.","k":"contrite"},{"t":"contusion","p":"noun","d":"vết bầm, thương tích","e":"The contusions on his face suggested he’d been in a fight.","ev":"Những vết bầm trên mặt anh cho thấy anh đã tham gia vào một cuộc ẩu đả.","k":"contusion"},{"t":"convene","p":"verb","d":"triệu tập, gọi lại","e":"Jason convened his entire extended family for a discussion.","ev":"Jason đã triệu tập cả gia đình để thảo luận.","k":"convene"},{"t":"convention","p":"noun","d":"1. hội nghị, 2. quy tắc, phong tục","e":"1. The hotel was full because of the cattle ranchers’ convention. 2. The cattle-ranchers have a convention that you take off your boots before entering their houses.","ev":"1. Khách sạn đầy vì hội nghị của những người chăn nuôi gia súc. 2. Có quy tắc là phải bỏ giày trước khi vào nhà họ.","k":"convention"},{"t":"convivial","p":"adjective","d":"vui vẻ, hòa đồng","e":"The restaurant’s convivial atmosphere put me immediately at ease.","ev":"Không khí vui vẻ của nhà hàng giúp tôi cảm thấy thoải mái ngay lập tức.","k":"convivial"},{"t":"convoluted","p":"adjective","d":"phức tạp, rắc rối","e":"Grace’s story was so convoluted that I couldn’t follow it.","ev":"Câu chuyện của Grace phức tạp đến mức tôi không thể theo kịp.","k":"convoluted"},{"t":"copious","p":"adjective","d":"phong phú, dồi dào","e":"Copious amounts of Snapple were imbibed in the cafeteria.","ev":"Một lượng lớn Snapple đã được tiêu thụ ở căng tin.","k":"copious"},{"t":"cordial","p":"adjective","d":"thân mật, ấm áp","e":"His cordial greeting melted my anger at once.","ev":"Lời chào thân mật của anh ấy làm tôi nguôi giận ngay lập tức.","k":"cordial"},{"t":"coronation","p":"noun","d":"lễ đăng quang","e":"The new king’s coronation occurred the day after his father’s death.","ev":"Lễ đăng quang của nhà vua mới diễn ra một ngày sau khi cha ông qua đời.","k":"coronation"},{"t":"corpulence","p":"adjective","d":"béo phì, mập mạp","e":"Henry’s corpulence did not make him any less attractive to his charming, svelte wife.","ev":"Sự mập mạp của Henry không làm giảm đi sức hấp dẫn của anh với vợ mình.","k":"corpulence"},{"t":"corroborate","p":"verb","d":"xác minh, chứng thực","e":"Luke’s seemingly outrageous claim was corroborated by witnesses.","ev":"Yêu cầu có vẻ ngớ ngẩn của Luke đã được chứng thực bởi các nhân chứng.","k":"corroborate"},{"t":"corrosive","p":"adjective","d":"ăn mòn, phá hủy","e":"The effect of the chemical was highly corrosive.","ev":"Hóa chất này có tác động ăn mòn rất mạnh.","k":"corrosive"},{"t":"cosmopolitan","p":"adjective","d":"tinh tế, thế giới","e":"Lloyd’s education and upbringing were cosmopolitan, so he felt right at home among the powerful and learned.","ev":"Giáo dục của Lloyd rất tinh tế, nên anh cảm thấy thoải mái giữa những người quyền lực.","k":"cosmopolitan"},{"t":"counteract","p":"verb","d":"chống lại, làm mất tác dụng","e":"The antidote counteracted the effect of the poison.","ev":"Thuốc giải độc đã làm mất tác dụng của chất độc.","k":"counteract"}]},{"n":"Buổi 36","c":[{"t":"coup","p":"noun","d":"hành động bất ngờ, 2. cuộc đảo chính","e":"Alexander pulled off an amazing coup when he got a date with Cynthia by purposely getting hit by her car. 2. In their coup attempt, the army officers stormed the Parliament and took all the legislators hostage.","ev":"Alexander đã thực hiện một cú sốc khi hẹn hò với Cynthia. 2. Trong cuộc đảo chính, các sĩ quan quân đội đã tấn công Quốc hội.","k":"coup"},{"t":"covet","p":"verb","d":"thèm muốn, ghen tị","e":"I coveted Moses’s house, wife, and car.","ev":"Tôi thèm muốn nhà, vợ và xe của Moses.","k":"covet"},{"t":"covert","p":"adjective","d":"bí mật, lén lút","e":"Nerwin waged a covert campaign against his enemies, while outwardly appearing to remain friendly.","ev":"Nerwin đã thực hiện một chiến dịch bí mật chống lại kẻ thù.","k":"covert"},{"t":"credulity","p":"noun","d":"tính cả tin","e":"His credulity made him an easy target for con men.","ev":"Sự cả tin của anh khiến anh dễ trở thành mục tiêu của kẻ lừa đảo.","k":"credulity"},{"t":"crescendo","p":"noun","d":"sự tăng dần","e":"The crescendo of the brass instruments gave the piece a patriotic feel.","ev":"Sự tăng dần của nhạc cụ đồng cho bản nhạc cảm giác yêu nước.","k":"crescendo"},{"t":"criteria","p":"noun","d":"tiêu chí, tiêu chuẩn","e":"Among Mrs. Fields’s criteria for good cookies are that they be moist and chewy.","ev":"Một trong những tiêu chí của bà Fields cho bánh quy là phải ẩm và dai.","k":"criteria"},{"t":"culmination","p":"noun","d":"sự đạt đến đỉnh cao","e":"The culmination of the couple’s argument was the decision to divorce.","ev":"Đỉnh điểm của cuộc tranh cãi của cặp đôi là quyết định ly hôn.","k":"culmination"},{"t":"culpable","p":"adjective","d":"đáng khiển trách","e":"He was culpable of the crime, and was sentenced to perform community service for 75 years.","ev":"Anh ta bị kết án vì tội và phải làm dịch vụ cộng đồng trong 75 năm.","k":"culpable"},{"t":"cultivate","p":"verb","d":"trau dồi, nuôi dưỡng","e":"At the library, she cultivated her interest in spy novels.","ev":"Cô đã nuôi dưỡng sở thích với tiểu thuyết gián điệp tại thư viện.","k":"cultivate"},{"t":"cumulative","p":"adjective","d":"tích lũy, dồn lại","e":"The cumulative effect of hours spent in the sun was a deep tan.","ev":"Tác động dồn lại của việc ở dưới nắng nhiều giờ là làn da rám nắng.","k":"cumulative"},{"t":"cunning","p":"adjective","d":"xảo quyệt, khôn ngoan","e":"The general devised a cunning plan to surprise the enemy.","ev":"Tướng đã nghĩ ra một kế hoạch xảo quyệt để bất ngờ kẻ thù.","k":"cunning"},{"t":"cupidity","p":"noun","d":"tham lam, dục vọng mạnh mẽ","e":"His cupidity made him enter the abandoned gold mine despite the obvious dangers.","ev":"Sự tham lam khiến anh vào mỏ vàng bỏ hoang mặc dù có nhiều nguy hiểm.","k":"cupidity"},{"t":"cursory","p":"adjective","d":"hời hợt, qua loa","e":"Late for the meeting, she cast a cursory glance at the agenda.","ev":"Đến muộn cho cuộc họp, cô đã liếc qua chương trình một cách hời hợt.","k":"cursory"},{"t":"curt","p":"adjective","d":"ngắn gọn, thô lỗ","e":"Her curt reply to my question made me realize that she was upset at me.","ev":"Câu trả lời ngắn gọn của cô khiến tôi nhận ra rằng cô đang bực mình.","k":"curt"},{"t":"curtail","p":"verb","d":"cắt giảm, hạn chế","e":"Since losing his job, he had to curtail his spending.","ev":"Kể từ khi mất việc, anh đã phải cắt giảm chi tiêu.","k":"curtail"},{"t":"daunting","p":"adjective","d":"đáng sợ, làm mất can đảm","e":"He kept delaying the daunting act of asking for a promotion.","ev":"Anh cứ trì hoãn việc đáng sợ là yêu cầu thăng chức.","k":"daunting"},{"t":"dearth","p":"noun","d":"sự thiếu hụt","e":"An eager reader, she was dismayed by the dearth of classic books at the library.","ev":"Là một độc giả háo hức, cô rất thất vọng vì thiếu sách cổ điển tại thư viện.","k":"dearth"},{"t":"debacle","p":"noun","d":"sự thất bại thảm hại","e":"The elaborately designed fireworks show turned into a debacle when the fireworks started firing in random directions.","ev":"Màn bắn pháo hoa được thiết kế tinh vi đã trở thành thảm họa khi pháo nổ hướng ngẫu nhiên.","k":"debacle"},{"t":"debase","p":"verb","d":"hạ thấp chất lượng","e":"The large raise that he gave himself debased his motives for running the charity.","ev":"Sự tăng lương lớn mà anh tự thưởng làm giảm giá trị của động cơ của anh khi điều hành quỹ từ thiện.","k":"debase"},{"t":"debauch","p":"verb","d":"làm hư hỏng, tha hóa","e":"An endless amount of good wine and cheese debauched the traveler.","ev":"Một lượng rượu và phô mai vô tận đã khiến người du lịch sa vào cám dỗ.","k":"debauch"},{"t":"debunk","p":"verb","d":"vạch trần sự giả mạo","e":"He debunked her claim to be the world’s greatest chess player by defeating her in 18 consecutive matches.","ev":"Anh đã vạch trần tuyên bố của cô là người chơi cờ vĩ đại nhất thế giới bằng cách đánh bại cô trong 18 trận liên tiếp.","k":"debunk"}]}]});
